-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (7481, 9, 'Mehr Personal und Ausstattung für Staatsanwaltschaften und Gerichte, gemeinsam mit den Ländern (Bund)', 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'belegt', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'bund', null, true, 'blind'),
  (7482, 9, 'Personal, Ausstattung und Befugnisse von Polizei und Ermittlungsbehörden stärken (Bund)', 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'gemischt', null, 'bund', null, true, 'blind'),
  (7483, 9, 'Digitalisierung von Justiz und Gerichtsverfahren (Bund)', 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'offen', null, 'bund', null, true, 'blind'),
  (7484, 9, 'KI-gestützte Datenanalyse und erweiterte digitale Ermittlungsbefugnisse (Bund)', 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'offen', null, 'bund', null, true, 'blind'),
  (7485, 9, 'Vorratsdatenspeicherung und weitere Überwachungsbefugnisse ablehnen oder zurücknehmen (Bund)', 'Das Ablehnen von Befugnissen schützt Grundrechte, bringt die Aufklärung aber nicht voran. Laut einer Studie des Max-Planck-Instituts brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung, der Verlust wäre also gering.', 'gemischt', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'bund', null, true, 'blind'),
  (7486, 9, 'Quick-Freeze-Verfahren zur Datensicherung im Verdachtsfall (Bund)', 'Quick Freeze ist grundrechtsschonend und schnell umsetzbar. Es greift aber nur bei Daten, die zum Zeitpunkt der Anordnung noch vorhanden sind. Bei IP-Adressen ist das oft nicht mehr der Fall, daher ist der Nutzen bei Onlinebetrug begrenzt.', 'gemischt', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'bund', null, true, 'blind'),
  (7487, 9, 'Login-Falle zur Identifizierung anonymer Täter im Netz (Bund)', 'Die Login-Falle kann anonyme Konten gezielt identifizieren und ist rechtlich wenig umstritten. Sie wirkt aber nur bei Konten, die erneut genutzt werden, und erfasst Betrug aus dem Ausland kaum. Zur Wirkung gibt es kaum Daten.', 'offen', null, 'bund', null, true, 'blind'),
  (7488, 9, 'Europol zu einem europäischen Kriminalamt ausbauen, grenznahe Polizeizusammenarbeit stärken (Bund)', 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'offen', null, 'bund', null, true, 'blind'),
  (7489, 9, 'Organisierte Kriminalität: Vermögensabschöpfung erleichtern, Beweislast umkehren, Geldwäsche bekämpfen (Bund)', 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'offen', null, 'bund', null, true, 'blind'),
  (7490, 9, 'Bagatelldelikte entkriminalisieren und Ersatzfreiheitsstrafen vermeiden, um die Justiz zu entlasten (Bund)', 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'belegt', null, 'bund', null, true, 'blind'),
  (7491, 9, 'Strafen für einzelne Gewalt- und Sexualdelikte verschärfen (Bund)', 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'belegt', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'bund', null, true, 'blind'),
  (7492, 9, 'Jugendstrafrecht verschärfen: Strafmündigkeit senken, Heranwachsende nach Erwachsenenstrafrecht (Bund)', 'Dafür spricht, dass Intensivtäter früher gestoppt werden können. Rückfallstudien zeigen aber keinen Vorteil härterer Sanktionen bei jungen Menschen, eher höhere Rückfallraten. Für Kinder fehlen zudem geeignete Einrichtungen.', 'belegt', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'bund', null, true, 'blind'),
  (7493, 9, 'Zustimmungslösung im Sexualstrafrecht („Nur Ja heißt Ja“) (Bund)', 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'gemischt', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'bund', null, true, 'blind'),
  (7494, 9, 'Frauenhäuser und Beratung ausbauen, Rechtsanspruch auf Schutz mit Bundesfinanzierung (Bund)', 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'belegt', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'bund', null, true, 'blind'),
  (7495, 9, 'Elektronische Fußfessel und schärferes Gewaltschutzgesetz bei häuslicher Gewalt (Bund)', 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'belegt', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'bund', null, true, 'blind'),
  (7496, 9, 'Täterarbeit und Prävention gegen Partnerschaftsgewalt ausbauen (Bund)', 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'gemischt', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'bund', null, true, 'blind'),
  (7497, 9, 'Ausweisung und Abschiebung ausländischer Straftäter erleichtern und vorrangig betreiben (Bund)', 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'offen', 'https://www.swp-berlin.org/10.18449/2021S12/', 'bund', null, true, 'blind'),
  (7498, 9, 'Nachrichtendienste und Gefährderüberwachung mit Personal und Befugnissen stärken (Bund)', 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'offen', null, 'bund', null, true, 'blind'),
  (7499, 9, 'Verfassungsschutz grundlegend umbauen oder durch andere Stelle ersetzen (Bund)', 'Bekannte Fehler wie im V-Leute-System sprechen für eine Reform. Ein Umbau kann aber zunächst die Früherkennung schwächen. Belege, dass eine andere Organisationsform extremistische Taten besser verhindert, fehlen.', 'offen', null, 'bund', null, true, 'blind'),
  (7500, 9, 'Vereins- und Organisationsverbote gegen extremistische Gruppen (Bund)', 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'offen', null, 'bund', null, true, 'blind'),
  (7501, 9, 'Extremisten konsequent entwaffnen (Bund)', 'Ohne legale Waffen sind schwere Gewalttaten von Extremisten schwerer möglich, und das Waffenrecht erlaubt den Entzug bereits. Illegal beschaffte Waffen erfasst die Maßnahme nicht, und Wirkungsstudien fehlen.', 'offen', null, 'bund', null, true, 'blind'),
  (7502, 9, 'Ausstiegs- und Präventionsangebote gegen Extremismus dauerhaft finanzieren (Bund)', 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'gemischt', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'bund', null, true, 'blind'),
  (7503, 9, 'Neue Straftatbestände gegen extremistische Propaganda (Bund)', 'Neue Straftatbestände können Werbung für Terror oder verfassungsfeindliche Ziele früher ahnden. Sie überschneiden sich teils mit geltendem Recht und müssen vor der Meinungsfreiheit bestehen. Zur Wirkung auf Gewalttaten gibt es keine Belege.', 'offen', null, 'bund', null, true, 'blind'),
  (7504, 9, 'Staatliche Förderung für extremistennahe Vereine ausschließen (Bund)', 'Die Maßnahme verhindert, dass extremistische Strukturen staatlich mitfinanziert werden. Auf Straftaten wirkt sie nur indirekt. Ein Ausschluss allein wegen einer Beobachtung oder wegen einzelner Mitglieder ist rechtlich angreifbar.', 'offen', null, 'bund', null, true, 'blind'),
  (7505, 9, 'Kriminalstatistik reformieren und Periodischen Sicherheitsbericht gesetzlich verankern (Bund)', 'Wissenschaftlich eingeordnete Lagebilder können verzerrte Wahrnehmungen korrigieren und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung tatsächlich ändern, ist kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (7506, 9, 'Sichtbare Polizeipräsenz und Kontrollen an Kriminalitätsschwerpunkten (Bund)', 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'belegt', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'bund', null, true, 'blind'),
  (7507, 9, 'Flächendeckende Videoüberwachung und Gesichtserkennung im öffentlichen Raum ablehnen (Bund)', 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'gemischt', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'bund', null, true, 'blind'),
  (7626, 9, 'Gezielte Polizeipräsenz und Streifen an Kriminalitätsschwerpunkten wie Bahnhöfen und Parks (Land)', 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'belegt', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'land', null, true, 'blind'),
  (7627, 9, 'Mehr sichtbare Polizeipräsenz und Streifen im öffentlichen Raum allgemein (Land)', 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'gemischt', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'land', null, true, 'blind'),
  (7628, 9, 'Mehr Sicherheitspersonal an Bahnhöfen, Haltestellen und im Nahverkehr (Land)', 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'belegt', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'land', null, true, 'blind'),
  (7629, 9, 'Bessere Beleuchtung und städtebauliche Kriminalprävention an Angsträumen (Land)', 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'belegt', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'land', null, true, 'blind'),
  (7630, 9, 'Videoüberwachung an kriminalitätsbelasteten Orten ausbauen (Land)', 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'belegt', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'land', null, true, 'blind'),
  (7631, 9, 'Flächendeckende Videoüberwachung und biometrische Gesichtserkennung ablehnen (Land)', 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'gemischt', null, 'land', null, true, 'blind'),
  (7632, 9, 'Anlasslose Kontrollen und Sonderbefugnisse an kriminalitätsbelasteten Orten ausweiten (Land)', 'Die Evaluation der Leipziger Waffenverbotszone fand weniger bewaffnete Angriffe, aber kaum Wirkung auf andere Taten. Anlasslose Kontrollen können Vertrauen kosten. Das Land kann sie im Polizeigesetz regeln.', 'gemischt', 'https://medienservice.sachsen.de/medien/news/252888', 'land', null, true, 'blind'),
  (7633, 9, 'Waffenverbotszonen und anlasslose Kontrollen abschaffen oder eng begrenzen (Land)', 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'gemischt', null, 'land', null, true, 'blind'),
  (7634, 9, 'Aufsuchende Sozialarbeit, Drogenhilfe, Konsumräume und Parkläufer an belasteten Orten (Land)', 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'gemischt', null, 'land', null, true, 'blind'),
  (7635, 9, 'Polizeipersonal aufstocken oder halten, Nachwuchsgewinnung und Bezahlung verbessern (Land)', 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'gemischt', null, 'land', null, true, 'blind'),
  (7636, 9, 'Ausstattung und Digitalisierung der Polizei, Entlastung von Verwaltungsarbeit (Land)', 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'offen', null, 'land', null, true, 'blind'),
  (7637, 9, 'Mehr Personal für Gerichte und Staatsanwaltschaften, Justizberufe attraktiver machen (Land)', 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'belegt', null, 'land', null, true, 'blind'),
  (7638, 9, 'Digitalisierung der Justiz und elektronische Akte (Land)', 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'offen', null, 'land', null, true, 'blind'),
  (7639, 9, 'Beschleunigte und vereinfachte Strafverfahren stärker nutzen, auch bei Jugendlichen (Land)', 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'gemischt', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'land', null, true, 'blind'),
  (7640, 9, 'Häuser des Jugendrechts und behördenübergreifende Zusammenarbeit bei Jugendstraftaten (Land)', 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'gemischt', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'land', null, true, 'blind'),
  (7641, 9, 'Jugendstrafrecht verschärfen über den Bund: Strafmündigkeit senken, Heranwachsende, Warnschussarrest (Land)', 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'belegt', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'land', null, true, 'blind'),
  (7642, 9, 'Gewaltprävention an Schulen, Jugend- und Schulsozialarbeit, Streetwork mit Präventionsauftrag (Land)', 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'gemischt', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'land', null, true, 'blind'),
  (7643, 9, 'Frauenhausplätze, Schutzwohnungen und Beratung ausbauen und dauerhaft finanzieren (Land)', 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'belegt', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'land', null, true, 'blind'),
  (7644, 9, 'Täterarbeit bei häuslicher Gewalt ausbauen, auch als verpflichtende Auflage (Land)', 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'gemischt', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'land', null, true, 'blind'),
  (7645, 9, 'Hochrisikomanagement, Gefährdungsanalyse und Fallkonferenzen bei häuslicher Gewalt (Land)', 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'gemischt', null, 'land', null, true, 'blind'),
  (7646, 9, 'Elektronische Fußfessel, Wegweisung, Kontakt- und Näherungsverbote bei häuslicher Gewalt (Land)', 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'gemischt', null, 'land', null, true, 'blind'),
  (7647, 9, 'Femizide einheitlich definieren und systematisch erfassen (Land)', 'Eine einheitliche Erfassung verbessert das Lagebild und kann Prävention gezielter machen. Sie verhindert selbst keine Taten, und zur Wirkung gibt es kaum Daten.', 'offen', null, 'land', null, true, 'blind'),
  (7648, 9, 'Landesaktionsplan oder Koordinierungsstelle gegen geschlechtsspezifische Gewalt (Land)', 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'offen', null, 'land', null, true, 'blind'),
  (7649, 9, 'Spezialisierte Zuständigkeiten in der Justiz für geschlechtsspezifische und sexualisierte Gewalt (Land)', 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'offen', null, 'land', null, true, 'blind'),
  (7650, 9, 'Gewaltschutz vor Umgangsrecht gewalttätiger Elternteile über den Bund (Land)', 'Gewalt setzt sich nach Trennungen oft bei Umgangskontakten fort; ein Vorrang des Schutzes setzt dort an. Das Familienrecht regelt der Bund, das Land kann nur werben, und zur Wirkung gibt es kaum Daten.', 'offen', null, 'land', null, true, 'blind'),
  (7651, 9, 'Strafen für einzelne Delikte über den Bund verschärfen (Land)', 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'belegt', null, 'land', null, true, 'blind'),
  (7652, 9, 'Gewaltschutzambulanzen und vertrauliche Spurensicherung flächendeckend ausbauen (Land)', 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'offen', null, 'land', null, true, 'blind'),
  (7653, 9, 'Herkunft von Tatverdächtigen in Statistiken, Lagebildern und Polizeimeldungen häufiger ausweisen (Land)', 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'offen', null, 'land', null, true, 'blind'),
  (7654, 9, 'Periodischer Sicherheitsbericht, Dunkelfeldbefragungen und wissenschaftliche Einordnung der Kriminalstatistik (Land)', 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (7655, 9, 'Vermögensabschöpfung und Finanzermittlungen gegen organisierte Kriminalität (Land)', 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (7656, 9, 'Beweislastumkehr bei der Einziehung kriminellen Vermögens über den Bund (Land)', 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'offen', null, 'land', null, true, 'blind'),
  (7657, 9, 'Spezialisierte Ermittlungsgruppen gegen organisierte Kriminalität (Land)', 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (7658, 9, 'Fahren ohne Fahrschein entkriminalisieren und Ersatzfreiheitsstrafe abschaffen über den Bund (Land)', 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'belegt', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'land', null, true, 'blind'),
  (7659, 9, 'Überwachungsbefugnisse und automatisierte Datenanalyse ablehnen oder begrenzen (Land)', 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'gemischt', null, 'land', null, true, 'blind'),
  (7660, 9, 'Quick-Freeze-Verfahren statt Vorratsdatenspeicherung über den Bund (Land)', 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'gemischt', null, 'land', null, true, 'blind'),
  (7661, 9, 'KI-gestützte Datenanalyse, Auswertesoftware und behördenübergreifendes Datenmanagement ausbauen (Land)', 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'offen', null, 'land', null, true, 'blind'),
  (8640, 9, 'Bodycams für Polizeikräfte mit Einschaltpflicht und Schutz der Aufnahmen (Land)', 'Laut Campbell-Übersichtsstudie senken Bodycams Beschwerden etwas, Gewaltanwendung und Festnahmen aber nicht verlässlich; Folgen für Aufklärung und Verurteilungen sind kaum untersucht. Das Land kann Einsatz und Pflichten im Polizeigesetz regeln.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'land', null, true, 'blind'),
  (8641, 9, 'Unabhängige Ermittlungs- oder Beschwerdestelle für mutmaßliche Polizeigewalt (Land)', 'Polizeigewalt wird laut einer Opferbefragung (KviAPol) nur selten angezeigt und verfolgt; eine unabhängige Stelle setzt dort an. Ob solche Stellen mehr Taten aufklären, ist kaum untersucht, und sie betreffen nur einen kleinen Teil der Straftaten.', 'offen', 'https://www.lto.de/recht/nachrichten/n/studie-polizeigewalt-singelnstein-zwischenbericht', 'land', null, true, 'blind'),
  (8642, 9, 'Bagatellverfahren im Land häufiger einstellen, etwa Fahren ohne Fahrschein oder geringe Drogenmengen (Land)', 'Allein Fahren ohne Fahrschein führte 2021 zu über 38.000 Verurteilungen und fast einem Viertel der Ersatzfreiheitsstrafen; Einstellungsrichtlinien des Landes entlasten die Justiz rasch. Schwerere Taten werden dadurch nur indirekt schneller verfolgt.', 'belegt', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'land', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 9 and id not in (7481, 7482, 7483, 7484, 7485, 7486, 7487, 7488, 7489, 7490, 7491, 7492, 7493, 7494, 7495, 7496, 7497, 7498, 7499, 7500, 7501, 7502, 7503, 7504, 7505, 7506, 7507, 7626, 7627, 7628, 7629, 7630, 7631, 7632, 7633, 7634, 7635, 7636, 7637, 7638, 7639, 7640, 7641, 7642, 7643, 7644, 7645, 7646, 7647, 7648, 7649, 7650, 7651, 7652, 7653, 7654, 7655, 7656, 7657, 7658, 7659, 7660, 7661, 8640, 8641, 8642);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (7508, 9, 11, null, 'Videoschutz an öffentlichen Gefahrenorten ausbauen und automatisierte Gesichtserkennung an Bahnhöfen, Flughäfen und Kriminalitätsschwerpunkten einsetzen.', '{901}', null, 1, 1, null, 'Kameras an Brennpunkten senken laut Meta-Analyse leicht die Kriminalität, kaum aber Gewalt. Automatische Gesichtserkennung im öffentlichen Raum lässt die KI-Verordnung der EU nur in engen Ausnahmen zu.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7509, 9, 11, null, 'Digitale Befugnisse für alle Bundessicherheitsbehörden: Quellen-TKÜ, Online-Durchsuchung und automatische Datenanalyse mit KI.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7510, 9, 11, null, 'Gerichte personell besser ausstatten, konkurrenzfähig besolden, digitalisieren und Verfahren beschleunigen.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7511, 9, 11, null, 'Beweislastumkehr beim Einziehen von Vermögen unklarer Herkunft, Geldwäsche konsequenter bekämpfen.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7512, 9, 11, null, 'Auf Heranwachsende von 18 bis 21 Jahren soll künftig allgemeines Strafrecht statt Jugendstrafrecht angewendet werden.', '{903}', 7492, 1, 2, null, 'Dafür spricht, dass Intensivtäter früher gestoppt werden können. Rückfallstudien zeigen aber keinen Vorteil härterer Sanktionen bei jungen Menschen, eher höhere Rückfallraten. Für Kinder fehlen zudem geeignete Einrichtungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'belegt', '2026-10-02', false, true, 'blind'),
  (7513, 9, 11, null, 'Strafrecht verschärfen zum besseren Schutz besonders gefährdeter Gruppen, vor allem Frauen; Höchststrafe für Stalking erhöhen.', '{904}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-02', false, true, 'blind'),
  (7514, 9, 11, null, 'Sicherheitskonzept für Opfer häuslicher Gewalt entwickeln und Frauenhäuser stärken.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7515, 9, 11, null, 'Elektronische Fußfessel verstärkt einsetzen, damit Gewalttäter Abstand zu ehemaligen Partnerinnen halten.', '{904}', 7495, 2, 3, null, 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'belegt', '2026-10-02', false, true, 'blind'),
  (7516, 9, 11, null, 'Gruppenvergewaltigungen und Körperverletzungen mit Messer deutlich härter bestrafen.', '{908,902}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-02', false, true, 'blind'),
  (7517, 9, 11, null, 'Regelmäßige Abschiebungen nach Afghanistan und Syrien, vor allem von Straftätern und Gefährdern.', '{905,907}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7518, 9, 11, null, 'Ausreisepflichtige Straftäter und Gefährder nach der Haft in unbefristeten Ausreisearrest nehmen können.', '{905,907}', null, 1, 0, null, 'Die Haft würde Gefährder bis zur Ausreise festhalten. Unbefristeter Arrest verstößt aber gegen die EU-Rückführungsrichtlinie (höchstens 18 Monate) und gegen das Grundrecht auf Freiheit.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7519, 9, 11, null, 'Speicherpflicht für IP-Adressen und Portnummern für Internetanbieter.', '{906,907}', null, 2, 2, null, 'Ohne gespeicherte IP-Adressen bleiben viele Hinweise auf Online-Taten unaufklärbar. Eine Max-Planck-Studie fand für die frühere Vorratsdatenspeicherung aber keine höhere Aufklärungsquote. Das EU-Recht lässt eine Speicherpflicht nur in engen Grenzen zu.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7520, 9, 11, null, 'Telekommunikationsüberwachung und Funkzellenauswertung ausweiten, insbesondere beim Enkeltrick.', '{906}', null, 1, 2, null, 'Mit Telekommunikationsüberwachung lassen sich Banden beim Enkeltrick verfolgen. Viele Täter sitzen aber im Ausland, und neue Befugnisse müssen vor dem Fernmeldegeheimnis bestehen. Zur Wirkung gibt es kaum Daten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7521, 9, 11, null, 'Europol stärken und zur Zentralstelle mit gemeinsamem Datenhaus ausbauen, auch gegen Cyberkriminalität und Terrorismus.', '{906,902}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=47', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7522, 9, 11, null, 'Nachrichtendiensten die notwendigen Befugnisse zur frühzeitigen Gefahrenaufklärung geben.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7523, 9, 11, null, 'Antisemitische Straftat führt zum Verlust des humanitären Schutzes und zur Abschiebung.', '{907}', null, 1, 1, null, 'Die Maßnahme entfernt antisemitische Straftäter und kann abschrecken. Ein Widerruf des Schutzstatus ist nach EU-Recht und Flüchtlingskonvention aber nur bei schweren Taten möglich und hängt von Herkunftsstaaten ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7524, 9, 11, null, 'Vereine und Verbände, die vom Verfassungsschutz beobachtet werden, von staatlichen Kooperationen und Geldern ausschließen.', '{907}', 7504, 1, 2, null, 'Die Maßnahme verhindert, dass extremistische Strukturen staatlich mitfinanziert werden. Auf Straftaten wirkt sie nur indirekt. Ein Ausschluss allein wegen einer Beobachtung oder wegen einzelner Mitglieder ist rechtlich angreifbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7525, 9, 11, null, 'Extremisten und Straftäter, die Feinde des Staates sind, entwaffnen.', '{907}', 7501, 2, 3, null, 'Ohne legale Waffen sind schwere Gewalttaten von Extremisten schwerer möglich, und das Waffenrecht erlaubt den Entzug bereits. Illegal beschaffte Waffen erfasst die Maßnahme nicht, und Wirkungsstudien fehlen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7526, 9, 11, null, 'Gesetz gegen Extremismus: Werben für Terrororganisationen wird strafbar, mit Regelausweisung und Verlust der Staatsangehörigkeit bei Doppelstaatlern.', '{907}', 7503, 1, 2, null, 'Neue Straftatbestände können Werbung für Terror oder verfassungsfeindliche Ziele früher ahnden. Sie überschneiden sich teils mit geltendem Recht und müssen vor der Meinungsfreiheit bestehen. Zur Wirkung auf Gewalttaten gibt es keine Belege.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7527, 9, 11, null, 'Bundesprogramm „Demokratie leben“ künftig im Bundesinnenministerium ansiedeln.', '{907}', null, 0, 3, null, 'Ein Ressortwechsel kann das Programm stärker mit der Sicherheitsarbeit verzahnen. Er ändert aber weder Umfang noch Inhalt der Prävention, daher ist keine Wirkung auf Straftaten zu erwarten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7528, 9, 11, null, 'Ambulante und stationäre Versorgungsangebote für psychische Erkrankungen bedarfsgerecht verbessern, besonders für Kinder und Jugendliche.', '{911}', null, 1, 2, null, 'Eine bessere ambulante und stationäre Versorgung erreicht auch schwer Erkrankte, deren Gewaltrisiko eine Behandlung senkt. Die Zusage ist aber allgemein und vor allem auf Kinder und Jugendliche ausgerichtet.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=70', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7529, 9, 12, null, 'Personalaufbau bei den Sicherheitsbehörden fortsetzen, begründet mit der Sichtbarkeit der Polizei.', '{901}', 7506, 2, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-02', false, true, 'blind'),
  (7530, 9, 12, null, 'Moderne Ausrüstung und zeitgemäße Befugnisse für Polizei- und Sicherheitsbehörden.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7531, 9, 12, null, 'Gesetzliche Grundlage für KI-gestützte Datenanalyse bei Bundeskriminalamt und Bundespolizei.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7532, 9, 12, null, 'Erneuter Pakt für den Rechtsstaat: Justiz mit den Ländern personell und materiell besser ausstatten.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7533, 9, 12, null, 'Strafprozessordnung auf Effektivität reformieren.', '{902}', null, 1, 2, null, 'Eine effizientere Strafprozessordnung kann Verfahren beschleunigen. Die Zusage nennt aber keinen Inhalt, und der Hauptengpass ist das Personal.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7534, 9, 12, null, 'Digitalisierung der Justiz mit bundesweit kompatiblen Systemen fortsetzen.', '{902}', 7483, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7535, 9, 12, null, 'Organisierte Kriminalität: Definition modernisieren und Sicherheitsbehörden stärken, Wirtschaftskriminalität im Fokus.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7536, 9, 12, null, 'Sexuelle Handlungen ohne eindeutiges Einverständnis unter Strafe stellen.', '{908}', 7493, 1, 3, null, 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7537, 9, 12, null, 'Erhebliche sexuelle Belästigung wie Catcalling unter Strafe stellen.', '{908}', null, 1, 3, null, 'Eine Strafbarkeit verbaler Belästigung macht deutlich, dass sie Unrecht ist, und schließt eine Lücke. Durchsetzen lässt sie sich aber schwer, weil Täter selten bekannt sind, und belastbare Wirkungsdaten fehlen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7538, 9, 12, null, 'Gewaltschutzgesetz verschärfen: Fußfessel, Anti-Gewalt-Trainings für Täter, Aufenthaltsverbote, Hausarrest.', '{904}', 7495, 2, 3, null, 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'belegt', '2026-10-02', false, true, 'blind'),
  (7539, 9, 12, null, 'Bundesweiter Rechtsanspruch auf Schutz und Beratung, Zugang zu Frauenhäusern und Beratungsstellen; Gewalthilfegesetz.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7540, 9, 12, null, 'Geschlechtsspezifische Gewalt EU-weit als Straftatbestand festschreiben lassen.', '{904}', null, 1, 1, null, 'Ein EU-weiter Straftatbestand vereinheitlicht den Schutz. In Deutschland sind die meisten Taten aber schon strafbar, und die Maßnahme hängt von einer Einigung in der EU ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7541, 9, 12, null, 'Log-in-Falle: IP-Adresse bei verdächtigem Benutzerkonto erfassen, um Stammdaten zu ermitteln.', '{906}', 7487, 1, 3, null, 'Die Login-Falle kann anonyme Konten gezielt identifizieren und ist rechtlich wenig umstritten. Sie wirkt aber nur bei Konten, die erneut genutzt werden, und erfasst Betrug aus dem Ausland kaum. Zur Wirkung gibt es kaum Daten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7542, 9, 12, null, 'Regeln gegen Hasskriminalität und Netzstraftaten umsetzen; Plattformbetreiber müssen illegale Inhalte entfernen.', '{906,907}', null, 1, 2, null, 'Löschpflichten verringern die Verbreitung von Hass und illegalen Inhalten. Sie führen aber nicht zur Verfolgung der Täter und helfen gegen Betrug kaum. Der europäische Digital Services Act lässt wenig Raum für eigene nationale Regeln.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7543, 9, 12, null, 'Finanzquellen rechtsextremistischer Netzwerke offenlegen und austrocknen.', '{907}', null, 1, 2, null, 'Wenn Finanzquellen wegfallen, verlieren Netzwerke Handlungsfähigkeit. Ein konkretes Instrument nennt die Zusage nicht, und Wirkungsstudien fehlen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7544, 9, 12, null, 'Islamismusprävention weiter stärken.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7545, 9, 12, null, 'Sicherheitsbehörden mit nötigen Mitteln ausstatten, um islamistische Netzwerke zu zerschlagen.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7546, 9, 12, null, 'Rasche und konsequente Abschiebungen bei verweigerter Ausreise, insbesondere von Straftätern.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=56', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7547, 9, 13, null, 'Bundespolizei und BKA sollen das nötige Personal, Technik, Know-how und verfassungskonforme Befugnisse erhalten.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7548, 9, 13, null, 'Neuauflage des Pakts für den Rechtsstaat mit den Ländern; genügend Richter und Staatsanwälte, gut ausgestattete Gerichte.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=113', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7549, 9, 13, null, 'Datenzugriff für Strafverfolgung im digitalen Raum über Quick-Freeze ausbauen.', '{902,906}', 7486, 1, 3, null, 'Quick Freeze ist grundrechtsschonend und schnell umsetzbar. Es greift aber nur bei Daten, die zum Zeitpunkt der Anordnung noch vorhanden sind. Bei IP-Adressen ist das oft nicht mehr der Fall, daher ist der Nutzen bei Onlinebetrug begrenzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7550, 9, 13, null, 'Geringfügige Delikte aus dem Strafrecht nehmen und Ersatzfreiheitsstrafe vermeiden, um die Justiz zu entlasten.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=114', null, 'belegt', '2026-10-02', false, true, 'blind'),
  (7551, 9, 13, null, 'KI-gestützte Analyseinstrumente der Polizei für die Strafverfolgung stärker nutzbar machen, polizeiliche Daten automatisiert verknüpfen.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7552, 9, 13, null, 'Gemeinsame Zentren der Polizei in Grenzregionen ausbauen, Europol zu einem Europäischen Kriminalamt weiterentwickeln.', '{902}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7553, 9, 13, null, 'Rechtsanspruch auf Schutz und Beratung bei Partnerschaftsgewalt; Frauenhäuser, Beratungsstellen und Schutzwohnungen mit Bundesbeteiligung flächendeckend sichern.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7554, 9, 13, null, 'Annäherungsverbote bei häuslicher Gewalt wirksam kontrollieren, auch mit elektronischer Fußfessel.', '{904}', 7495, 2, 3, null, 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'belegt', '2026-10-02', false, true, 'blind'),
  (7555, 9, 13, null, 'Istanbul-Konvention umsetzen mit mehr Prävention, Ausbau der Täterarbeit und konsequenter Strafverfolgung.', '{904}', 7496, 2, 2, null, 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7556, 9, 13, null, 'Sexualstrafrecht mit der Zustimmungslösung reformieren.', '{908}', 7493, 1, 3, null, 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7557, 9, 13, null, 'Einsatz von K.-o.-Tropfen bei sexuellen Übergriffen als strafverschärfenden Umstand ins Strafgesetzbuch aufnehmen.', '{908}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-02', false, true, 'blind'),
  (7558, 9, 13, null, 'Flächendeckend medizinische Notfallversorgung mit anonymer Spurensicherung für Vergewaltigungsopfer.', '{908}', null, 2, 3, null, 'Mit anonymer Spurensicherung können Betroffene Beweise sichern, bevor sie über eine Anzeige entscheiden. Das kann die Anzeigebereitschaft erhöhen. Krankenkassen zahlen schon, flächendeckend fehlt das Angebot. Studien zur Wirkung gibt es kaum.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7559, 9, 13, null, 'Ausreisepflichtige Straftäter nach Verbüßung der Strafe vorrangig zurückführen.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7560, 9, 13, null, 'BKA und Verfassungsschutz mit Personal, Technik und Befugnissen gegen Terrorismus ausstatten.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7561, 9, 13, null, 'Top-Gefährder länderübergreifend lückenlos überwachen und strafrechtlich verfolgen.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7562, 9, 13, null, 'Extremistische Netzwerke früh erkennen, Vereinsverbote konsequent aussprechen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7563, 9, 13, null, 'Verfassungsfeinde konsequent entwaffnen, besonders in der rechtsextremen Szene.', '{907}', 7501, 2, 3, null, 'Ohne legale Waffen sind schwere Gewalttaten von Extremisten schwerer möglich, und das Waffenrecht erlaubt den Entzug bereits. Illegal beschaffte Waffen erfasst die Maßnahme nicht, und Wirkungsstudien fehlen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7564, 9, 13, null, 'Ausstiegs- und Deradikalisierungsangebote finanziell stärken und per Demokratiefördergesetz absichern.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7565, 9, 13, null, 'Strafverfolgung bei Hasskriminalität im Netz stärken, auch mit Login-Falle und Accountsperren.', '{907,902}', 7487, 1, 3, null, 'Die Login-Falle kann anonyme Konten gezielt identifizieren und ist rechtlich wenig umstritten. Sie wirkt aber nur bei Konten, die erneut genutzt werden, und erfasst Betrug aus dem Ausland kaum. Zur Wirkung gibt es kaum Daten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=140', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7566, 9, 13, null, 'Periodischen Sicherheitsbericht gesetzlich verankern.', '{909}', 7505, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder können verzerrte Wahrnehmungen korrigieren und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung tatsächlich ändern, ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7567, 9, 13, null, 'Polizeistatistik reformieren, um Hasskriminalität besser zu erfassen.', '{909}', 7505, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder können verzerrte Wahrnehmungen korrigieren und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung tatsächlich ändern, ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7568, 9, 13, null, 'Psychiatrisch-psychosoziale Krisendienste bedarfsgerecht ausbauen und psychiatrische Versorgung stärken.', '{911}', null, 2, 2, null, 'Bei Psychosen und Sucht senkt Behandlung das Gewaltrisiko deutlich, Krisendienste erreichen Unbehandelte früh. Die meisten Gewalttaten gehen aber nicht auf Erkrankungen zurück. Der Ausbau liegt großteils bei Ländern und Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://www.aerztezeitung.de/Medizin/Ein-Risikofaktor-fuer-Gewalttaten-303442.html', 'belegt', '2026-10-02', false, true, 'blind'),
  (7569, 9, 13, null, 'Waffenrecht verschärfen, Verfügbarkeit tödlicher Schusswaffen einschränken, Schreckschusswaffen nur mit kleinem Waffenschein.', '{901}', null, 1, 3, null, 'Weniger frei verfügbare gefährliche Waffen können Taten im öffentlichen Raum erschweren, und der Bund kann das Waffenrecht ändern. Schusswaffentaten mit legalen Waffen sind in Deutschland aber selten; die Wirkung ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7570, 9, 13, null, 'Angebote für Prävention, Therapie und Gesundheitsschutz bei Suchtmitteln ausbauen.', '{911}', null, 1, 2, null, 'Suchterkrankungen erhöhen das Gewaltrisiko, mehr Prävention und Therapie setzen dort an. Die Zusage ist allgemein und nennt keinen Bezug zu Gewalt. Die Angebote liegen überwiegend bei Ländern, Kommunen und Krankenkassen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7571, 9, 13, null, 'Einziehung von Vermögen aus kriminellen Machenschaften erleichtern und Vermögensabschöpfung stärker nutzbar machen.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=135', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7572, 9, 14, null, 'Keine flächendeckende Überwachung im öffentlichen Raum und keine automatisierte Gesichtserkennung dort.', '{901}', 7507, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=24', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7573, 9, 14, null, 'Gerichte und Verfahrensrecht weiter digitalisieren, etwa mit Online-Gerichtsverfahren.', '{902}', 7483, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7574, 9, 14, null, 'Strafgesetzbuch überprüfen, überholte Straftatbestände streichen oder anpassen; Schwarzfahren nur noch als Ordnungswidrigkeit.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'belegt', '2026-10-02', false, true, 'blind'),
  (7575, 9, 14, null, 'Europol zu einem Europäischen Kriminalamt ausbauen, gegen Terrorismus, organisierte und Cyberkriminalität.', '{902,906,907}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=22', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7576, 9, 14, null, 'Clans und organisierte Kriminalität bekämpfen: Geldwäsche unterbinden, Vermögen aus Straftaten einziehen.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7577, 9, 14, null, 'Quick-Freeze statt Vorratsdatenspeicherung: Daten im Verdachtsfall auf richterliche Anordnung sichern.', '{906}', 7486, 1, 3, null, 'Quick Freeze ist grundrechtsschonend und schnell umsetzbar. Es greift aber nur bei Daten, die zum Zeitpunkt der Anordnung noch vorhanden sind. Bei IP-Adressen ist das oft nicht mehr der Fall, daher ist der Nutzen bei Onlinebetrug begrenzt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=24', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7578, 9, 14, null, 'Nachrichtendienste erhalten klarere Rechtsgrundlagen; zersplitterte Kontrolle neu ordnen, Lücken schließen.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=22', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7579, 9, 14, null, 'Mehr Betätigungs- und Organisationsverbote für antisemitische Organisationen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=51', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7580, 9, 14, null, 'Sicherheitsbehörden sollen gefährdete Gruppen und ihre Einrichtungen besser schützen.', '{907}', null, 1, 2, null, 'Der Schutz gefährdeter Einrichtungen kann Anschläge verhindern. Die Zusage nennt aber kein konkretes Instrument, und der Objektschutz liegt meist bei der Landespolizei.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7581, 9, 14, null, 'Gegen Radikalisierung durch islamistische Influencer im Internet neben Strafrecht auch ausländerrechtliche Maßnahmen einsetzen.', '{907}', null, 1, 2, null, 'Strafrecht und Ausweisung können einzelne radikalisierende Akteure stoppen. Viele Influencer wirken aber aus dem Ausland oder sind Deutsche, und die Wirkung ist unbelegt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7582, 9, 14, null, 'Frauenhausplätze bedarfsgerecht ausfinanzieren und freie Plätze über eine bundesweite Online-Plattform in Echtzeit anzeigen.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7583, 9, 15, null, 'Ausweisung ausländischer Straftäter, besonders bei Gewalt-, Drogen- und Sexualdelikten sowie organisierter und Clankriminalität, deutlich erleichtern.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=102', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7584, 9, 15, null, 'Ausländische Gefährder, Extremisten und schwere Straftäter vorrangig zurückführen.', '{905,907}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=102', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7585, 9, 15, null, 'Grenzen wieder selbst kontrollieren, Bundespolizei als Grenzbehörde einsetzen und Einreisende an der Grenze zurückweisen; auch zur Bekämpfung grenzüberschreitender Kriminalität.', '{905}', null, 1, 1, null, 'Grenzkontrollen können einzelne grenzüberschreitende Taten aufdecken. Auf die Ursachen der Überrepräsentation wirken sie kaum. Dauerhafte Kontrollen und Zurückweisungen sind nach Schengen- und EU-Asylrecht nur eng zulässig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7586, 9, 15, null, 'Ermittlungsbehörden erheblich bei Personal und Ausstattung aufstocken.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=118', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7587, 9, 15, null, 'Justizpersonal aufstocken und Rechtssystem stärken.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=120', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7588, 9, 15, null, 'Strafverfolgungsbefugnisse und Fahndungsmöglichkeiten der Polizei an die Kriminalitätsentwicklung anpassen.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7589, 9, 15, null, 'Strafaussetzung zur Bewährung bei Haftstrafen nur nach Mindestverbüßung.', '{902}', null, 1, 2, null, 'Eine Mindesthaft macht Strafen spürbarer. Mehr Strafaussetzung hat aber nach deutschen Daten den Rückfall nicht erhöht, und Haft wirkt nicht besser. Volle Gefängnisse der Länder sind eine Hürde.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=120', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'belegt', '2026-10-02', false, true, 'blind'),
  (7590, 9, 15, null, 'Durch Straftaten erworbenes Vermögen konsequent einziehen, mit Nachweispflicht zur Herkunft bei Straftätern und Familienmitgliedern.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=118', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7591, 9, 15, null, 'In sogenannten No-go-Areas Mittel bereitstellen und Razzien und Kontrollstellen durchführen, um den Rechtsstaat durchzusetzen.', '{901}', 7506, 2, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=123', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-02', false, true, 'blind'),
  (7592, 9, 15, null, 'Flächendeckende Videoüberwachung ablehnen.', '{901}', 7507, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=125', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7593, 9, 15, null, 'Waffenrecht neu fassen; statt Legalwaffenbesitzer zu belasten, illegalen Waffenbesitz und -handel bekämpfen.', '{901}', null, 1, 2, null, 'Viele Waffentaten werden mit illegalen Waffen begangen, daher setzt die Maßnahme an. Sie nennt aber kein konkretes Instrument, und illegale Märkte sind schwer zu kontrollieren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=121', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7594, 9, 15, null, 'Strafmündigkeit auf 12 Jahre senken, Jugendstrafrecht nur bis 18, zeitnahe Haft für Mehrfach- und Intensivtäter.', '{903}', 7492, 1, 2, null, 'Dafür spricht, dass Intensivtäter früher gestoppt werden können. Rückfallstudien zeigen aber keinen Vorteil härterer Sanktionen bei jungen Menschen, eher höhere Rückfallraten. Für Kinder fehlen zudem geeignete Einrichtungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'belegt', '2026-10-02', false, true, 'blind'),
  (7595, 9, 15, null, 'Organisationen des gewaltsamen Linksextremismus verbieten und ihre Symbole unter Strafe stellen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=121', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7596, 9, 15, null, 'Vereine und Verbände, die Extremisten unterstützen, von staatlichen Mittelzuwendungen ausschließen.', '{907}', 7504, 1, 2, null, 'Die Maßnahme verhindert, dass extremistische Strukturen staatlich mitfinanziert werden. Auf Straftaten wirkt sie nur indirekt. Ein Ausschluss allein wegen einer Beobachtung oder wegen einzelner Mitglieder ist rechtlich angreifbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=122', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7597, 9, 15, null, 'Öffentliche Forderung nach einem Kalifat unter Strafe stellen; ausländische Teilnehmer abschieben.', '{907}', 7503, 1, 2, null, 'Neue Straftatbestände können Werbung für Terror oder verfassungsfeindliche Ziele früher ahnden. Sie überschneiden sich teils mit geltendem Recht und müssen vor der Meinungsfreiheit bestehen. Zur Wirkung auf Gewalttaten gibt es keine Belege.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=122', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7598, 9, 15, null, 'Verfassungsschutz grundsätzlich reformieren; Terrorabwehr und Spionageabwehr bei Bundesnachrichtendienst und Polizei.', '{907}', 7499, 1, 2, null, 'Bekannte Fehler wie im V-Leute-System sprechen für eine Reform. Ein Umbau kann aber zunächst die Früherkennung schwächen. Belege, dass eine andere Organisationsform extremistische Taten besser verhindert, fehlen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=139', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7599, 9, 15, null, 'Angriffe auf Juden und antisemitische Beleidigungen konsequent strafrechtlich ahnden.', '{907}', null, 1, 2, null, 'Eine konsequente Verfolgung antisemitischer Taten kann Täter abschrecken und Betroffene ermutigen, Taten anzuzeigen. Die Zusage nennt aber kein Instrument wie Schwerpunktstaatsanwaltschaften, und die Strafverfolgung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=124', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7600, 9, 16, null, 'Sicherheitskonzepte im öffentlichen Raum sollen nicht pauschal kontrollieren und anlasslos flächendeckend überwachen; Soziale Prävention statt Überwachung.', '{901}', 7507, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7601, 9, 16, null, 'Obdachlose und Suchtabhängige nicht aus Innenstädten verdrängen, sondern bessere Hilfsangebote und mehr Sozialarbeit.', '{901}', null, 1, 2, null, 'Sozialarbeit und Hilfen vor Ort können Konflikte an Brennpunkten in Innenstädten entschärfen. Für das Sicherheitsgefühl ist die Wirkung kaum untersucht. Zuständig sind vor allem Kommunen, der Bund kann nur fördern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7602, 9, 16, null, 'Kriminalpolizei und Staatsanwaltschaft sollen in die Lage versetzt werden, mit neuen Kriminalitätsformen Schritt zu halten, auch bei Cyber-Attacken.', '{902,906}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7603, 9, 16, null, 'Ermittlungsbefugnisse nicht ausweiten: gegen Vorratsdatenspeicherung, Onlinedurchsuchungen, Rasterfahndung und allgegenwärtige Videoüberwachung.', '{902,901,906}', 7485, 0, 3, null, 'Das Ablehnen von Befugnissen schützt Grundrechte, bringt die Aufklärung aber nicht voran. Laut einer Studie des Max-Planck-Instituts brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung, der Verlust wäre also gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7604, 9, 16, null, 'Drogenkonsum vollständig entkriminalisieren und medizinische sowie sozialarbeiterische Interventionsprogramme schaffen.', '{902,911}', null, 1, 2, null, 'Weniger Konsumverfahren entlasten Polizei und Justiz, und Hilfsprogramme erreichen Abhängige. Auf die Aufklärung schwerer Taten wirkt das nur indirekt. Die Wirkung einer vollständigen Entkriminalisierung ist umstritten, internationale Abkommen setzen Grenzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7605, 9, 16, null, 'Verfassungsschutz durch unabhängige Beobachtungsstelle ersetzen; V-Leute-System aufdecken und beenden.', '{907}', 7499, 1, 2, null, 'Bekannte Fehler wie im V-Leute-System sprechen für eine Reform. Ein Umbau kann aber zunächst die Früherkennung schwächen. Belege, dass eine andere Organisationsform extremistische Taten besser verhindert, fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7606, 9, 16, null, 'Demokratiefördergesetz mit dauerhafter Finanzierung für Beratung gegen Rechtsextremismus, Opferberatung und Demokratiebündnisse.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7607, 9, 16, null, 'Verbot militanter, bewaffneter, neonazistischer Organisationen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7608, 9, 16, null, 'Ausfinanzierter Aktionsplan gegen queerfeindliche Gewalt und Diskriminierung.', '{907}', null, 1, 2, null, 'Ein Aktionsplan kann Prävention und Erfassung queerfeindlicher Hasskriminalität bündeln. Er nennt aber kein konkretes Instrument gegen Straftaten, und die Wirkung solcher Pläne ist kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7609, 9, 16, null, 'Istanbul-Konvention vollständig umsetzen; Frauenhäuser verlässlich finanzieren; Schutz und Beratung kostenfrei und überall verfügbar.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7610, 9, 16, null, 'Gewaltschutz im Sorge- und Umgangsrecht verankern.', '{904}', null, 2, 3, null, 'Trennung und Umgangskontakte sind Hochrisikophasen; wenn Gewaltschutz im Sorgerecht Vorrang hat, sinken die Gelegenheiten für Taten. Der Bund kann das selbst regeln. Wirkungsstudien fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7611, 9, 16, null, 'Prinzip „Nur Ja heißt Ja“ gesetzlich verankern und gezielt gegen Netzwerke sexualisierter Gewalt vorgehen.', '{908}', 7493, 1, 3, null, 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7612, 9, 16, null, 'Awareness-Konzepte gegen sexualisierte Gewalt als Pflichtbestandteil von Sicherheitskonzepten bei Großveranstaltungen.', '{908}', null, 1, 2, null, 'Awareness-Konzepte bieten Betroffenen bei Großveranstaltungen schnelle Hilfe und können Übergriffe verhindern. Sie erreichen nur einen kleinen Teil der Taten, und die Auflagen für Veranstaltungen regeln vor allem Länder und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7613, 9, 16, null, 'Straftäter ohne Abschiebung: reguläres Strafverfahren und Haftverbüßung im Inland unabhängig vom Aufenthaltsstatus.', '{905}', null, 0, 3, null, 'Die Maßnahme entspricht im Wesentlichen der geltenden Rechtslage und schützt rechtsstaatliche Gleichbehandlung. An den Ursachen der Überrepräsentation setzt sie aber nicht an.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7614, 9, 16, null, 'Haftung für Onlinemarktplätze und Onlineplattformen.', '{906}', null, 1, 1, null, 'Eine Haftung von Plattformen würde Anreize gegen Fake-Shops und Betrug setzen. Die Haftungsregeln legt aber der europäische Digital Services Act abschließend fest, Deutschland kann sie nicht allein ändern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=56', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7615, 9, 17, null, 'Polizei so besetzen, dass sie sichtbar auf Straßen und öffentlichen Plätzen präsent ist; dafür ausreichend Personal.', '{901}', 7506, 2, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-02', false, true, 'blind'),
  (7616, 9, 17, null, 'Polizei solide mit modernen Einsatzmitteln und IT ausstatten, auch gegen Cyberkriminalität und Terrorismus; Aus- und Fortbildung.', '{902,906,907}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7617, 9, 17, null, 'Deutlich mehr Personal in den Justizbehörden und weniger Verfahren durch Reformen, besonders im Strafrecht.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7618, 9, 17, null, 'Beleidigung von Politikern aus dem Strafgesetzbuch streichen, um Polizei und Ermittlungsbehörden zu entlasten.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'belegt', '2026-10-02', false, true, 'blind'),
  (7619, 9, 17, null, 'Sammeln und Speichern individueller Verhaltensdaten verbieten und Vorratsdatenspeicherung stoppen.', '{902,906}', 7485, 0, 3, null, 'Das Ablehnen von Befugnissen schützt Grundrechte, bringt die Aufklärung aber nicht voran. Laut einer Studie des Max-Planck-Instituts brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung, der Verlust wäre also gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=43', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7620, 9, 17, null, 'Gewaltschutz- und Hilfesysteme ausbauen, mehr Frauenhausplätze und Schutzwohnungen, langfristige Finanzierung durch den Bund, kostenfreie Nutzung.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7621, 9, 17, null, 'Angebote der Täterarbeit und Anti-Aggressionstrainings ausbauen.', '{904}', 7496, 2, 2, null, 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=34', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7622, 9, 17, null, 'Information und Sensibilisierung zum Gewaltschutz fester Bestandteil im Bildungscurriculum an Schulen und Hochschulen.', '{904,903}', null, 1, 1, null, 'Gewaltschutz im Unterricht kann junge Menschen früh für Grenzen und Hilfsangebote sensibilisieren. Die Wirkung schulischer Programme ist uneinheitlich belegt, und für Lehrpläne sind allein die Länder zuständig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7623, 9, 17, null, 'Zuwanderer, die schwere Straftaten begehen, ausweisen und notfalls abschieben; Verfahren dazu vorrangig und zügig führen.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7624, 9, 17, null, 'Beobachtungsbereich „Delegitimierung des Staates“ beim Verfassungsschutz abschaffen.', '{907}', null, 0, 3, null, 'Die Abschaffung eines Beobachtungsbereichs ist leicht umsetzbar und kann Eingriffe in politische Meinungsäußerung verringern. Weniger politisch motivierte Straftaten sind davon aber nicht zu erwarten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7625, 9, 17, null, 'Finanzierung von Projekten und Organisationen, die den öffentlichen Diskurs beeinflussen sollen, beenden; Demokratiefördergesetz ablehnen.', '{907}', null, 0, 3, null, 'Das Ende der Förderung spart Geld und beendet den Vorwurf politischer Einflussnahme. Es streicht aber auch Prävention und Ausstiegsarbeit gegen Extremismus. Weniger Straftaten sind dadurch nicht zu erwarten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=39', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7662, 9, 11, 'BE', 'Videoüberwachung an allen kriminalitätsbelasteten Orten ausbauen, auch mit intelligenten Systemen', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=10', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7663, 9, 11, 'BE', 'Neue Polizeiwache am Leopoldplatz mit sichtbarer Präsenz, um Drogenkriminalität entgegenzutreten', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7664, 9, 11, 'BE', 'Verdachtsunabhängige Personenkontrollen ermöglichen; Räume kurzfristig zu kriminalitätsbelasteten Orten erklären', '{901}', 7632, 1, 3, null, 'Die Evaluation der Leipziger Waffenverbotszone fand weniger bewaffnete Angriffe, aber kaum Wirkung auf andere Taten. Anlasslose Kontrollen können Vertrauen kosten. Das Land kann sie im Polizeigesetz regeln.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', 'https://medienservice.sachsen.de/medien/news/252888', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7665, 9, 11, 'BE', 'Angsträume abbauen durch bessere Beleuchtung, übersichtliche Wegeführung und gepflegte Unterführungen', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=10', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7666, 9, 11, 'BE', 'Mehr sichtbares Sicherheitspersonal, mehr Videoüberwachung und Notrufsäulen im Nahverkehr', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=72', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7667, 9, 11, 'BE', 'Strafrechtliche Ahndung des unerlaubten Umgangs mit halbautomatischen Kurzwaffen durch eigenen Verbrechenstatbestand', '{901}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=19', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7668, 9, 11, 'BE', 'Neue Wege bei der Personalgewinnung für die Polizei', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=7', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7669, 9, 11, 'BE', 'Strafverfolgungsbehörden personell und technisch deutlich stärken, am Bedarf ausrichten', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=19', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7670, 9, 11, 'BE', 'Polizei von Bürokratie entlasten, Dokumentationspflichten abbauen, Verfahren digitalisieren', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7671, 9, 11, 'BE', 'Technische Ermittlungsinstrumente ausbauen: KI-Datenanalyse, Auswertesoftware, Speicherung von IP-Adressen', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=20', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7672, 9, 11, 'BE', 'Vermögensabschöpfung gegen organisierte Kriminalität und Clanstrukturen weiter stärken', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=19', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7673, 9, 11, 'BE', 'Auf Bundesebene Haftgründe verschärfen, damit Wiederholungstäter schneller in Untersuchungshaft kommen', '{902}', null, 1, 1, null, 'Mehr Untersuchungshaft kann Wiederholungstaten bis zum Urteil verhindern. Die Haftgründe regelt der Bund, Haft verlangt Verhältnismäßigkeit, und Belege zur Wirkung fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=9', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7674, 9, 11, 'BE', 'Strafmündigkeit auf Bundesebene von 14 auf 12 Jahre senken, gerichtliches Verantwortungsverfahren', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=24', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7675, 9, 11, 'BE', 'Schuldistanz- und Jugenddelinquenz-Teams flächendeckend in allen Jugendämtern ausbauen', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7676, 9, 11, 'BE', 'Elektronische Fußfessel bei Hochrisiko-Gefährdern ausweiten, um Kontakt- und Näherungsverbote zu überwachen', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7677, 9, 11, 'BE', 'Zusätzliche Schutzplätze, Beratungs- und Interventionsangebote und ein zehntes Frauenhaus', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7678, 9, 11, 'BE', 'Verpflichtende Täterarbeit und niedrigschwellige Beratung ausbauen', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7679, 9, 11, 'BE', 'Regelmäßige Dunkelfeldstudien als Teil der Prävention von Gewalt gegen Frauen', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7680, 9, 11, 'MV', 'Mehr Polizei in Innenstädten und an Kriminalitätsschwerpunkten, höherer Kontrolldruck, wirksamere Platzverweise und Aufenthaltsverbote', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7681, 9, 11, 'MV', 'Angsträume verhindern, unter anderem durch ausgeweitete Videoüberwachung', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=6', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7682, 9, 11, 'MV', 'Modernes Beleuchtungsmanagement und bauliche Maßnahmen für mehr Sicherheit in Städten', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=32', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7683, 9, 11, 'MV', 'Polizei-Soll-Stärke erreichen, Einstellungszahlen erhöhen', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=27', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7684, 9, 11, 'MV', '50 zusätzliche Stellen bei den Staatsanwaltschaften und angemessene Personalausstattung der Gerichte', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=33', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7685, 9, 11, 'MV', 'Mehrjähriges IT-Investitionsprogramm für die Landespolizei', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7686, 9, 11, 'MV', 'Digitalisierung der Justiz ausweiten, elektronische Akte in allen Rechtsgebieten', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=34', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7687, 9, 11, 'MV', 'Vorratsdatenspeicherung auf Bundesebene einfordern', '{902}', null, 1, 1, null, 'Laut einer Max-Planck-Studie brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung; andere sehen Nutzen bei Onlinetaten. Das Land kann nur auf Bundesebene werben, und das EU-Recht setzt enge Grenzen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7688, 9, 11, 'MV', 'Einziehung von Vermögen aus kriminellen Geschäften per Beweislastumkehr erleichtern', '{902}', 7656, 1, 1, null, 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7689, 9, 11, 'MV', 'Dauerhafte Ermittlungsgruppen gegen Organisierte und Clan-Kriminalität', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7690, 9, 11, 'MV', 'Beschleunigte Verfahren im Jugendstrafrecht', '{903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7691, 9, 11, 'MV', 'Jugendlichen Mehrfach- und Intensivtätern durch bessere Kooperation und schnelleren Datenaustausch begegnen', '{903}', 7640, 2, 3, null, 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7692, 9, 11, 'MV', 'Präventive Kontakt- und Näherungsverbote durch die Polizei ausweiten, Gewaltpräventionsberatung für Gefährder', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7693, 9, 11, 'MV', 'Vernetzung der Akteure im Gewaltschutz zur Beschleunigung von Verfahren bei häuslicher Gewalt', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=34', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7694, 9, 11, 'ST', 'Videoschutz im öffentlichen Raum ausweiten, um Straftaten aufzuklären und zu verhindern', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7695, 9, 11, 'ST', 'Sichtbarkeit der Landespolizei in den Revieren vor Ort erhöhen', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=6', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7696, 9, 11, 'ST', 'Personalaufwuchs bei der Landespolizei fortsetzen, mit Zielgröße für Vollzug und Verwaltung', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=6', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7697, 9, 11, 'ST', 'KI-gestützten Videoschutz landesweit ermöglichen, um auffällige Verhaltensmuster zu erkennen und Fahndungserfolge zu erzielen', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7698, 9, 11, 'ST', 'Gesetzliche Grundlage für biogeographische Analyse von DNA-Spuren schaffen', '{902}', null, 1, 1, null, 'Die biogeographische Analyse kann bei unbekannten Tätern Ermittlungshinweise geben. Die Strafprozessordnung regelt der Bund, das Land kann nur werben, und der Nutzen ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7699, 9, 11, 'ST', 'Bedrohungs- und Gefährdungsmanagement einrichten, zentrale Gefahrenanalyse und behördenübergreifendes Datenmanagement', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7700, 9, 11, 'ST', 'Beschleunigte Verfahren mit Zielzeiten und digitaler Infrastruktur, damit Straftaten unmittelbar geahndet werden', '{902}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7701, 9, 11, 'ST', 'Nachwuchsgewinnung für die Justiz ausbauen und Justizberufe attraktiver machen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7702, 9, 11, 'ST', 'Vollständige elektronische Aktenführung in der Justiz einführen', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7703, 9, 11, 'ST', 'Opferschutz ausbauen und Finanzierung ambulanter Beratungsstellen und Frauenhäuser sichern', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7704, 9, 11, 'ST', 'Jugendliche in Schülergremien stärken, die im Umfeld beginnender Jugendkriminalität die Rechtsordnung bei Gleichaltrigen vermitteln', '{903}', null, 1, 3, null, 'Gleichaltrige können Regeln glaubwürdig vermitteln. Wie Schülergremien gegen beginnende Jugendkriminalität wirken, ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7705, 9, 12, 'BE', 'Fuß- und Fahrradstreifen der Polizei stadtweit ausweiten', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7706, 9, 12, 'BE', 'U- und S-Bahnhöfe häufiger mit Sicherheitspersonal besetzen', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7707, 9, 12, 'BE', 'Sicherheit im öffentlichen Raum: Haltestellen überdachen und beleuchten, mehr BVG-Streifen, besetzte Bahnhöfe, Heimwegtelefon', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7708, 9, 12, 'BE', 'Drogenabhängige vor Ort unterstützen statt vertreiben, Drogen aus dem öffentlichen Raum holen, Drogenkonsumräume ausbauen', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7709, 9, 12, 'BE', 'Waffen- und Messerverbotszonen nur als Ausnahme (Einschränkung)', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7710, 9, 12, 'BE', 'Verdachtsunabhängige Kontrollen räumlich und im Anwendungsbereich auf das Notwendige beschränken', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7711, 9, 12, 'BE', 'Ausrüstung und Infrastruktur der Polizei modernisieren', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7712, 9, 12, 'BE', 'Verfahrensdauern in der Justiz durch bessere Abläufe, Digitalisierung und zusätzliche Stellen verkürzen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7713, 9, 12, 'BE', 'Ersatzfreiheitsstrafen schrittweise durch soziale Arbeit ersetzen', '{902}', null, 1, 3, null, 'Gemeinnützige Arbeit statt Ersatzfreiheitsstrafe entlastet Justiz und Vollzug und lässt sich vom Land selbst ausbauen. Die Aufklärung schwerer Taten verbessert das nur indirekt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7714, 9, 12, 'BE', 'Keine Palantir-Software für die Berliner Polizei (Verzicht auf Massendatenauswertung dieser Art)', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7715, 9, 12, 'BE', 'Kriminell erworbenes Vermögen konsequent abschöpfen', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7716, 9, 12, 'BE', 'Spezialisierte Ermittlungsstrukturen bei Polizei und Staatsanwaltschaft gegen organisierte Kriminalität stärken', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7717, 9, 12, 'BE', 'Programme zur gewaltfreien Konfliktlösung und Prävention in den Kiezen fördern, Schwerpunkt häusliche Gewalt sowie Waffen- und Messergewalt', '{904}', null, 1, 2, null, 'Programme zur gewaltfreien Konfliktlösung in Stadtteilen können häuslicher Gewalt vorbeugen. Ihre Wirkung ist kaum untersucht, und der Umfang bleibt offen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7718, 9, 12, 'BE', 'Systematische Risikoanalysen der Polizei zur Früherkennung von Hochrisikofällen bei Gewalt gegen Frauen', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7719, 9, 12, 'BE', 'Istanbul-Konvention umsetzen, Frauenhäuser, Schutzwohnungen, Täterarbeit und Gewaltschutzambulanzen stadtweit ausbauen', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7720, 9, 12, 'BE', 'Einrichtungen zum Schutz von Frauen vor Gewalt per Trägerfinanzierung längerfristig sichern', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7721, 9, 12, 'BE', 'Auf Bundesebene Vorrang des Gewaltschutzes vor dem Umgangsrecht gewalttätiger Elternteile durchsetzen', '{904}', 7650, 1, 1, null, 'Gewalt setzt sich nach Trennungen oft bei Umgangskontakten fort; ein Vorrang des Schutzes setzt dort an. Das Familienrecht regelt der Bund, das Land kann nur werben, und zur Wirkung gibt es kaum Daten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7722, 9, 12, 'BE', 'Spezialisierte Beratungsstellen gegen Gewalt gegen Frauen stärken und Aufklärungsquoten erhöhen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7723, 9, 12, 'BE', 'Kostenübernahme der Vertraulichen Spurensicherung durch Krankenkassen erreichen', '{908}', null, 1, 2, null, 'Die Kostenübernahme erleichtert Spurensicherung ohne Anzeige. Das Sozialrecht sieht sie seit 2020 grundsätzlich vor, offen sind vor allem Verträge vor Ort; der Zusatznutzen ist daher gering.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7724, 9, 12, 'BE', 'Regelmäßige Dunkelfeldforschung zu den wichtigsten Kriminalitätsphänomenen fördern', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7725, 9, 12, 'MV', 'Sicherheit und Ordnung an Bahnhöfen, Haltestellen und in Bussen und Bahnen mit Kommunen, Verkehrsunternehmen, Polizei und Ordnungsbehörden stärken.', '{901}', null, 1, 3, null, 'Abgestimmtes Vorgehen von Polizei, Kommunen und Verkehrsunternehmen kann Bahnhöfe und Haltestellen sicherer machen. Ohne konkretes Instrument bleibt der Umfang offen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=46', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7726, 9, 12, 'MV', 'Personalstand der Landespolizei auf Mindestniveau halten und Präsenz der Polizei in der Fläche sichern.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=46', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7727, 9, 12, 'MV', 'Hohe Ausbildungskapazität der Polizeifachhochschule sichern, um Personalaufwuchs auf knapp 6.200 Polizeibeschäftigte zu erreichen.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=47', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7728, 9, 12, 'MV', 'Polizeiarbeit durch Fortsetzung der Digitalisierungsstrategie modernisieren und von Mehrfacharbeiten entlasten.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=47', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7729, 9, 12, 'MV', 'Bei polizeilichen Analysesystemen auf Palantir verzichten und eine europäische Alternative einsetzen.', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=47', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7730, 9, 12, 'MV', 'Personalausstattung der Justiz mit Richterinnen, Staatsanwältinnen und Rechtspflegern auf hohem Niveau erhalten.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7731, 9, 12, 'MV', 'Digitalisierung der Justiz weiter vorantreiben, damit Verfahren einfacher und schneller werden.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7732, 9, 12, 'MV', 'Situation von Frauenschutzhäusern, Beratungsstellen und Täterberatung verbessern; Frauenhäuser mit Investitionsmitteln modernisieren und bedarfsgerecht ausbauen.', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7733, 9, 12, 'MV', 'Freiwillige Schulungen für Richterinnen und Richter zu Femiziden und zur Istanbul-Konvention anbieten.', '{904}', null, 1, 3, null, 'Geschulte Richterinnen und Richter können Gefahren bei Partnerschaftsgewalt besser erkennen. Freiwillige Schulungen erreichen aber nicht alle, und zur Wirkung gibt es kaum Daten.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7734, 9, 12, 'MV', 'Auf Bundesebene erreichen, dass der Umgang mit Kindern zugunsten des Opferschutzes ausgesetzt werden kann, wenn ein Elternteil Opfer des anderen ist.', '{904}', 7650, 1, 1, null, 'Gewalt setzt sich nach Trennungen oft bei Umgangskontakten fort; ein Vorrang des Schutzes setzt dort an. Das Familienrecht regelt der Bund, das Land kann nur werben, und zur Wirkung gibt es kaum Daten.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7735, 9, 12, 'ST', 'Dienstposten der Landespolizei voll finanzieren und Besoldung der Polizeibeschäftigten verbessern', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7736, 9, 12, 'ST', 'Gerichte und Staatsanwaltschaften personell und technisch stärken, kein Einstellungsstopp in der Justiz', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=31', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7737, 9, 12, 'ST', 'Verbindliches Digitalisierungskonzept für die Justiz, abgesicherte IT-Migration und Einführung der E-Akte', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=31', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7738, 9, 12, 'ST', 'Häuser des Jugendrechts, in denen Polizei, Staatsanwaltschaft und Jugendhilfe Delikte Minderjähriger gemeinsam bearbeiten', '{903}', 7640, 2, 3, null, 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7739, 9, 12, 'ST', 'Frauenhäuser und Schutzwohnungen landesweit ausbauen; Istanbul-Konvention und Gewalthilfegesetz umsetzen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7740, 9, 12, 'ST', 'Beratungsinfrastruktur gegen Gewalt an Frauen stärken, besonders im ländlichen Raum, mit mehrjährigen Förderverträgen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7741, 9, 13, 'BE', 'Community Policing: mehr Kontaktbereichsbeamte, mehr Fahrradstreifen und Präsenz an Hotspots, mobile Wachen und Kiezläufer', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7742, 9, 13, 'BE', 'Strategie „Sicherheit-Plus“: soziale Infrastruktur in Brennpunkten stärken, Aufenthaltsqualität des öffentlichen Raums verbessern, polizeiliche Präsenzmaßnahmen', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=232', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7743, 9, 13, 'BE', 'Ausreichende Beleuchtung auf den Wegen zu Haltestellen', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=82', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7744, 9, 13, 'BE', 'Mehr Sicherheit und Sauberkeit auf Bahnhöfen und in Bahnen; mehr geschulte Sicherheitsmitarbeitende der BVG, Frauenabteile in der U-Bahn erproben', '{901,908}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=82', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7745, 9, 13, 'BE', 'Videoüberwachung im öffentlichen Raum nicht flächendeckend, nur gezielt zum Schutz kritischer Infrastruktur ausbauen', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7746, 9, 13, 'BE', 'Konsumräume und Streetwork-Teams ausbauen, um besonders junge und sozial benachteiligte Menschen zu erreichen', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=209', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7747, 9, 13, 'BE', 'Polizeiausbildung attraktiver machen und Arbeitsbedingungen verbessern, um das Personal zu sichern', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7748, 9, 13, 'BE', 'Sanierungsstau bei Liegenschaften und Fuhrpark der Polizei abbauen, Neubau für das Kriminaltechnische Institut anschieben', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7749, 9, 13, 'BE', 'Personaloffensive in der Justiz mit besseren Arbeitsbedingungen, Quereinstiegen und Aufstiegschancen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=240', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7750, 9, 13, 'BE', 'Digitale Recherchetools und Assistenzsysteme in Rechtsprechung und Strafverfolgung unterstützen, um Gerichte und Staatsanwaltschaften zu entlasten', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=242', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7751, 9, 13, 'BE', 'Ersatzfreiheitsstrafe und Strafbarkeit von Bagatelldelikten wie Fahren ohne Fahrschein über den Bund abschaffen, Abarbeiten von Geldstrafen stärken', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=238', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7752, 9, 13, 'BE', 'Anlasslose Massenüberwachung wie biometrische Gesichtserkennung ablehnen; Absage an Vorratsdatenspeicherung im Bundesrat', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7753, 9, 13, 'BE', 'Immobilienregister mit wirtschaftlich Berechtigten, um kriminelle Strukturen aufzudecken und Immobilien einzuziehen', '{902}', null, 1, 1, null, 'Ein Register der wirtschaftlich Berechtigten erleichtert Ermittlungen gegen Geldwäsche mit Immobilien. Auf alltägliche Taten wirkt es kaum, und Grundbuch- und Registerrecht regelt weitgehend der Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=232', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7754, 9, 13, 'BE', 'Organisierte Kriminalität priorisieren: Strukturermittlungen bei LKA und Staatsanwaltschaft, Schnittstellen zu Finanzämtern, Steuerfahndung und Zoll', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=232', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7755, 9, 13, 'BE', 'Angebote der Jugendsozial- und Jugendkulturarbeit in belasteten Kiezen absichern, vor allem für junge Männer, als Kriminalprävention', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7756, 9, 13, 'BE', 'Ressortübergreifender Sicherheitsgipfel von Land und Bezirken gegen die Zunahme rechtsextremer Jugendgewalt', '{903}', null, 1, 3, null, 'Ein ressortübergreifender Gipfel kann Maßnahmen gegen rechtsextreme Jugendgewalt bündeln. Ein Treffen allein ändert wenig, konkrete Instrumente fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=160', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7757, 9, 13, 'BE', 'Zwei neue Frauenhäuser, mehr Beratungsangebote, Zweite-Stufe-Wohnungen und Schutzwohnungen mit Bundesmitteln aus dem Gewalthilfegesetz', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7758, 9, 13, 'BE', 'Elektronische Fußfessel mit Benachrichtigungsmöglichkeit für Betroffene einführen', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7759, 9, 13, 'BE', 'Standardisierte, regelbasierte Verfahren der Polizei bei geschlechtsspezifischer und häuslicher Gewalt nach spanischem Vorbild', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7760, 9, 13, 'BE', 'Istanbul-Konvention umsetzen: Prävention in Schulen und Sozialämtern sowie Täterarbeit wie Anti-Aggressionstrainings stärken', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7761, 9, 13, 'BE', 'Sonderzuständigkeit für Sexualdelikte an den Strafgerichten schaffen', '{908}', 7649, 1, 3, null, 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7762, 9, 13, 'BE', 'Über den Bund Catcalling unter Strafe stellen', '{908}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7763, 9, 13, 'BE', 'Berliner Periodischer Sicherheitsbericht neben der Polizeilichen Kriminalstatistik, der auch Ursachen von Taten analysiert', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7764, 9, 13, 'MV', 'Bürgernahe Polizei mit mehr Präsenz vor Ort, Beamte zu Fuß in den Quartieren', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7765, 9, 13, 'MV', 'Moratorium für biometrische Überwachung im öffentlichen Raum, stattdessen Prävention und Präsenz', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://gruene-mv.de/?wpdmdl=33772#page=74', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7766, 9, 13, 'MV', 'Soziale Präventionsarbeit in Kommunen finanziell stärken: Streetwork, Jugendclubs, Suchtberatung, psychologische Betreuung', '{901,903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7767, 9, 13, 'MV', 'Stadt- und Dorfplanung gendersensibel gestalten, u. a. mit sicheren Übergängen und guter Beleuchtung', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://gruene-mv.de/?wpdmdl=33772#page=85', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7768, 9, 13, 'MV', 'Ausreichende Neueinstellungen bei der Landespolizei und Reform der Aus- und Fortbildung', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7769, 9, 13, 'MV', 'Deutlich mehr Richter, Staatsanwälte und Justizbedienstete einstellen und angemessen bezahlen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://gruene-mv.de/?wpdmdl=33772#page=78', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7770, 9, 13, 'MV', 'Polizeigesetz mit hohen Hürden für Grundrechtseingriffe, ohne Online-Durchsuchung und Quellen-TKÜ', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7771, 9, 13, 'MV', 'Keine Zusammenarbeit der Sicherheitsbehörden mit Palantir', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://gruene-mv.de/?wpdmdl=33772#page=74', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7772, 9, 13, 'MV', 'Beratungs- und Hilfenetz gegen geschlechtsspezifische Gewalt dauerhaft finanzieren (Frauenhäuser, Beratung, Täterarbeit)', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7773, 9, 13, 'MV', 'Einheitliche Definition von Femiziden und systematische statistische Erfassung durch Polizei und Staatsanwaltschaften', '{904}', 7647, 1, 3, null, 'Eine einheitliche Erfassung verbessert das Lagebild und kann Prävention gezielter machen. Sie verhindert selbst keine Taten, und zur Wirkung gibt es kaum Daten.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7774, 9, 13, 'MV', 'Beratungs- und Hilfenetz für Opfer sexueller und häuslicher Gewalt auskömmlich finanzieren', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7775, 9, 13, 'MV', 'Periodischer Sicherheitsbericht, der die Kriminalstatistik allgemeinverständlich ergänzt', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7776, 9, 13, 'ST', 'Polizeifahrradstreifen als sichtbare, präventive Polizeipräsenz weiter fördern', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7777, 9, 13, 'ST', 'Mehr Sicherheit im Schienenverkehr durch Doppelbesetzung mit Zugbegleitung und Sicherheitsteams', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=31', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7778, 9, 13, 'ST', 'Sichere Haltestellen schaffen und Angsträume beseitigen', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=32', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7779, 9, 13, 'ST', 'Personalausbau bei der Polizei bis zur Zielgröße fortsetzen', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7780, 9, 13, 'ST', 'Bessere Personalausstattung von Gerichten und Staatsanwaltschaften für zügigere Verfahren', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7781, 9, 13, 'ST', 'Digitalisierung der Justiz mit E-Akte und digitalen Verfahren vorantreiben', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7782, 9, 13, 'ST', 'Fahren ohne Fahrschein nicht mehr als Straftat behandeln', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=31', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7783, 9, 13, 'ST', 'Jugendarbeit und Schulsozialarbeit massiv stärken, um früh präventiv zu wirken', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7784, 9, 13, 'ST', 'Bedarfsgerechter Ausbau von Frauenhäusern und Schutzräumen in allen Regionen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=44', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7785, 9, 13, 'ST', 'Gewalthilfegesetz umsetzen und Frauenhaus-Finanzierung ohne Eigenanteil der Bewohnerinnen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=44', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7786, 9, 13, 'ST', 'Fachstellen für Täterarbeit auch im ländlichen Raum fördern', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=45', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7787, 9, 13, 'ST', 'Alle Kliniken ans Netzwerk für anonyme Spurensicherung nach sexueller Gewalt anbinden', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=83', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7788, 9, 13, 'ST', 'Polizeiliche Kriminalstatistik durch Studien ergänzen und einordnen', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=42', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7789, 9, 14, 'BE', 'Dauerhafte, verstärkte Polizeipräsenz im öffentlichen Raum; Polizei von Verwaltungsaufgaben entlasten', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=66', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7790, 9, 14, 'BE', 'Sonderbefugnisse (anlasslose Identitätsfeststellung, Durchsuchung) der Polizei an kriminalitätsbelasteten Orten, mit klareren Kriterien für die Einstufung', '{901}', 7632, 1, 3, null, 'Die Evaluation der Leipziger Waffenverbotszone fand weniger bewaffnete Angriffe, aber kaum Wirkung auf andere Taten. Anlasslose Kontrollen können Vertrauen kosten. Das Land kann sie im Polizeigesetz regeln.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://medienservice.sachsen.de/medien/news/252888', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7791, 9, 14, 'BE', 'Security by Design: bauliche Sicherheit an Risikoorten wie Bahnhöfen durch Beleuchtung, Sichtachsen, keine dunklen Ecken, daneben temporäre Videoüberwachung', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7792, 9, 14, 'BE', 'Konsumräume und Streetwork-Teams ausbauen; Nachtcafés und Drogenkonsumräume im Kurfürstenkiez sichern', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=118', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7793, 9, 14, 'BE', 'Finanzierung des Parkläufer-Projekts verstetigen, um Konflikte in Grünanlagen zu deeskalieren und Parkordnungen durchzusetzen', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=70', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7794, 9, 14, 'BE', 'Personalsituation bei Polizei (und Justiz) verbessern: Bezahlung, Arbeitsplätze, Nachwuchsprogramm', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=72', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7795, 9, 14, 'BE', 'Statt anlassloser Datenspeicherung das Quick-Freeze-Verfahren nach richterlichem Beschluss einführen', '{902}', 7660, 1, 1, null, 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7796, 9, 14, 'BE', 'Clankriminalität bekämpfen, Vermögen aus Straftaten bei Tatverdacht auch per Beweislastumkehr abschöpfen', '{902}', 7656, 1, 1, null, 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7797, 9, 14, 'BE', 'Verfahren gegen straffällige Jugendliche unmittelbar nach der Tat (Neuköllner Modell) fortsetzen und verstetigen', '{903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7798, 9, 14, 'BE', 'Gewaltpräventive Angebote der Polizei an Schulen verstärken, Polizei, Schulen und Jugendhilfe verzahnen, mehr Jugend- und Sozialarbeit sowie Streetwork', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7799, 9, 14, 'BE', 'Gewaltschutzambulanz stärken und ausbauen, mehr Zufluchtsorte, bessere Zusammenarbeit der Institutionen bei häuslicher und sexualisierter Gewalt', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=69', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7800, 9, 14, 'BE', 'Schutz- und Beratungseinrichtungen nach Gewalthilfegesetz ausbauen und regelfinanzieren, mehr Schutzplätze in Frauenhäusern', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=80', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7801, 9, 14, 'BE', 'Täterarbeit bei häuslicher Gewalt deutlich ausbauen', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=81', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7802, 9, 14, 'BE', 'Höhere Strafandrohung im Gewaltschutzgesetz und bessere Durchsetzung gegen Stalking und Hasskriminalität', '{904}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7803, 9, 14, 'MV', 'Verlässliche Polizeipräsenz auch im ländlichen Raum sicherstellen', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7804, 9, 14, 'MV', 'Personalschlüssel der Landespolizei anpassen, mehr Beamte im operativen Dienst', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7805, 9, 14, 'MV', 'Zahl der Richter, Staatsanwälte und Justizmitarbeitenden bedarfsgerecht erhöhen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=138', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7806, 9, 14, 'MV', 'Digitalisierung der Justiz vorantreiben, Medienbrüche zwischen Polizei, Staatsanwaltschaft und Gerichten beenden', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=138', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7807, 9, 14, 'MV', 'Vollständig digitale Abläufe bei der Polizei mit interaktiven Streifenwagen und mobilen Endgeräten', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7808, 9, 14, 'MV', 'Anlasslose Vorratsdatenspeicherung ablehnen, stattdessen Quick-Freeze bei konkretem Verdacht', '{902}', 7660, 1, 1, null, 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=134', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7809, 9, 14, 'MV', 'Flächendeckende Videoüberwachung und automatisierte Gesichtserkennung ablehnen', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7810, 9, 14, 'MV', 'Femiziden entgegenwirken: Gefährdungsanalysen, Behördenabstimmung, elektronische Fußfessel bei häuslicher Gewalt per Landesrecht', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7811, 9, 14, 'MV', 'Finanzierung des Beratungs- und Hilfenetzes bei häuslicher und sexualisierter Gewalt stärken', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=53', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7812, 9, 14, 'MV', 'Straftaten ehrlich erfassen, einschließlich der Herkunft der Täter', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=132', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7813, 9, 14, 'ST', 'Sichtbar mehr Polizei in Stadt und Land: Zielzahl von 7.000 Stellen im Polizeivollzugsdienst halten.', '{902,901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=47', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7814, 9, 14, 'ST', 'Sicherheitspartnerschaften von Polizei und Ordnungsämtern flächendeckend ausbauen, gemeinsame Einsätze zum Regelfall machen, um die Präsenz im öffentlichen Raum zu erhöhen.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=47', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7815, 9, 14, 'ST', 'Alle Waffenverbotszonen im Land abschaffen, damit entfallen auch die anlasslosen Personenkontrollen dort.', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=48', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7816, 9, 14, 'ST', 'Elektronische Akte in allen Bereichen der Justiz bis spätestens 2030 landesweit einführen, ohne Medienbruch.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=45', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7817, 9, 14, 'ST', 'Frauenhäuser stärken und Ursachen häuslicher Gewalt bekämpfen; Eigenanteile für Übernachtungen in Frauenhäusern abschaffen als geeigneter Weg.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=39', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7818, 9, 15, 'BE', 'Videoüberwachung in allen Brennpunktbereichen einführen', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7819, 9, 15, 'BE', 'Mobile Polizeiwachen in Problemvierteln und dichteres Netz stationärer Wachen', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7820, 9, 15, 'BE', 'Strafrahmen und Schnellverfahren bei Messerdelikten, mehr anlasslose Kontrollen an kriminalitätsbelasteten Orten', '{901,902}', null, 1, 2, null, 'Kontrollen an belasteten Orten und Schnellverfahren setzen an, wirken laut Leipziger Evaluation aber nur begrenzt; höhere Strafen schrecken kaum ab. Den Strafrahmen ändert der Bund.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7821, 9, 15, 'BE', 'Mehr Personal bei Polizei und Justiz sowie ausreichende Ausbildung des Nachwuchses', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7822, 9, 15, 'BE', 'Bessere Ausrüstung und Arbeitsbedingungen für Polizei und Justiz, Sanierung von Gebäuden', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7823, 9, 15, 'BE', 'Digitale Infrastruktur für Polizei und Justiz, gegebenenfalls KI', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7824, 9, 15, 'BE', 'Bezirkspolizei bei den Ordnungsämtern mit Befugnissen zu Identitätsfeststellung, Platzverweis und unmittelbarem Zwang, zur Entlastung der Landespolizei', '{902}', null, 1, 2, null, 'Eine Ordnungspolizei der Bezirke kann die Landespolizei von einfachen Aufgaben entlasten und Zeit für Ermittlungen schaffen. Aufbau, Befugnisse und Personal brauchen Zeit, Belege fehlen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=12', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7825, 9, 15, 'BE', 'Verfahren gegen Mehrfachbeschuldigte beim selben Dezernenten bündeln, Staatsanwaltschaft neu strukturieren und enger mit Polizei verzahnen', '{902}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7826, 9, 15, 'BE', 'Tatverdächtige der organisierten Kriminalität binnen 48 Stunden dem Bereitschaftsrichter vorführen', '{902}', null, 1, 2, null, 'Eine schnelle Vorführung kann Verfahren gegen Tatverdächtige beschleunigen. Die Vorführung vor einen Richter ist ohnehin binnen eines Tages Pflicht, der Zusatznutzen ist unklar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=14', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7827, 9, 15, 'BE', 'Beschlagnahme und Einziehung kriminell erworbenen Vermögens konsequent bei Clans und organisierter Kriminalität anwenden', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=14', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7828, 9, 15, 'BE', 'Rechtsgrundlage für nächtliche Ausgangssperren für jugendliche Intensivtäter', '{903}', null, 1, 1, null, 'Nächtliche Ausgangssperren könnten Intensivtäter von Taten abhalten. Sie greifen stark in Grundrechte ein, sind rechtlich unsicher, und Belege zur Wirkung fehlen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7829, 9, 15, 'BE', 'Strafmündigkeit auf 12 senken, beschleunigte Jugendverfahren ausweiten, Warnschussarrest und Jugendstrafe früher möglich', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7830, 9, 15, 'BE', 'Migrationshintergrund von Tatverdächtigen klar benennen und statistisch erfassen, auch bei Deutschen', '{909}', null, 1, 2, null, 'Mehr Angaben zur Herkunft sollen Transparenz schaffen; ob das verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen. Die Kriminalstatistik ist bundeseinheitlich, ein Migrationshintergrund wird darin bisher nicht erfasst.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7831, 9, 15, 'MV', 'Sichtbare Polizeipräsenz auf den Straßen erhöhen und Polizei modern ausstatten, gegen gefährliche Plätze und Angst vor nächtlichen Spaziergängen.', '{901,902}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=11', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7832, 9, 15, 'MV', 'Polizeipersonal der Landespolizei auf dem Zielstand halten und genug Absolventen der Polizeifachhochschule ausbilden.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=37', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7833, 9, 15, 'MV', 'Polizeivollzugsbeamte durch Prozessoptimierung, Digitalisierung und nichtpolizeiliches Personal von Verwaltungsarbeit entlasten.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=37', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7834, 9, 15, 'MV', 'Quick-Freeze-Verfahren statt Vorratsdatenspeicherung stärken und KI-gestützte Auswertung sichergestellter Daten einsetzen.', '{902}', 7660, 1, 1, null, 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=43', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7835, 9, 15, 'MV', 'Staatsanwaltschaften sollen in einfach gelagerten Fällen häufiger das beschleunigte Strafverfahren nutzen, in Jugendsachen das vereinfachte Verfahren.', '{902,903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=44', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7836, 9, 15, 'MV', 'Bundesratsinitiative, die Strafmündigkeit von 14 auf 12 Jahre zu senken.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=44', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7837, 9, 15, 'MV', 'Gewalt an Schulen unterbinden und Schulsozialarbeit als Landesaufgabe etablieren.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7838, 9, 15, 'MV', 'Mehr Informationen zur Ausländerkriminalität in der Kriminalstatistik auch je Landkreis und kreisfreier Stadt veröffentlichen.', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7839, 9, 15, 'MV', 'In Polizei-Presseinformationen auf doppelte Staatsangehörigkeiten von Tatverdächtigen und Opfern hinweisen.', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7840, 9, 15, 'MV', 'Landeskriminalamt-Lagebild zu Kriminalität im Kontext von Zuwanderung mit Herkunftsstaaten und Täter-Opfer-Verhältnissen veröffentlichen.', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7841, 9, 15, 'MV', 'Regelmäßige landesweite Dunkelfeldbefragungen zu erlebter Kriminalität und Meiden öffentlicher Plätze.', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7842, 9, 15, 'ST', 'Landespolizei auf mindestens 7.500 Vollzugsbeamte aufstocken.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=105', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7843, 9, 15, 'ST', 'Freiwillige Bürgerwacht unter dem Ordnungsamt als zusätzliche Säule der Sicherheit vor Ort aufbauen, die Ordnungsamt und Polizei unterstützt.', '{901}', null, 1, 2, null, 'Freiwillige Streifen können Präsenz erhöhen und Ordnungsämter unterstützen. Ohne Befugnisse und Ausbildung ist ihr Beitrag begrenzt, und Belege zur Wirkung fehlen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=112', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7844, 9, 15, 'ST', 'Beschleunigte Verfahren stärker nutzen, besonders bei Straftaten von Jugendlichen schnelles Aburteilen (Neuköllner Modell).', '{902,903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=119', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7845, 9, 15, 'ST', 'Vorübergehender Stellenaufwuchs in der Justizverwaltung und Einstellungsoffensive im Justizvollzugsdienst.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=121', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7846, 9, 15, 'ST', 'Bei Gewaltverbrechen den Strafrahmen voll ausschöpfen; Richter sollen maximale Härte anwenden.', '{902,908}', null, 0, 1, null, 'Richter sind unabhängig, das Land kann ihnen keine Strafhöhe vorgeben. Zudem schreckt laut Forschung vor allem das Entdeckungsrisiko ab, kaum die Höhe der Strafe.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=119', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7847, 9, 15, 'ST', 'Strafmündigkeit auf Bundesebene von 14 auf 12 Jahre absenken.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=124', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7848, 9, 15, 'ST', 'Warnschussarrest bei jeder Form der Jugendkriminalität konsequent verhängen.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=109', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7849, 9, 15, 'ST', 'Rechtsfigur des Heranwachsenden im Jugendstrafrecht abschaffen, sodass diese Altersgruppe nach Erwachsenenstrafrecht behandelt wird.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=125', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7850, 9, 15, 'ST', 'Bei Bedarf privaten Wachdienst an Schulen einrichten, der Gewalt auf dem Schulhof verhindert.', '{903}', null, 1, 2, null, 'Wachpersonal kann Gewalt auf dem Schulhof unterbinden. Private Dienste haben aber keine hoheitlichen Befugnisse, Belege zur Wirkung fehlen, und Präventionsprogramme gelten als besser belegt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=88', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7851, 9, 15, 'ST', 'Schulen und Staatsanwaltschaften vernetzen, damit jede Straftat strafmündiger Schüler vor Gericht kommt; Gewalttäter schneller der Schule verweisen.', '{903}', null, 1, 2, null, 'Eine engere Verbindung von Schulen und Justiz setzt bei Jugendgewalt an. Jede Tat vor Gericht zu bringen widerspricht aber der Diversion, die laut Rückfallforschung nicht schlechter wirkt als formelle Verfahren.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=89', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7852, 9, 16, 'BE', 'Statt Zaun und nächtlicher Parkschließung Mittel für aufsuchende Sozialarbeit, Obdachlosen- und Suchthilfe sowie Parkläufer*innen einsetzen.', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7853, 9, 16, 'BE', 'Kriminalitätsbelastete Orte und Waffenverbotszonen samt Videoüberwachung und anlasslosen Kontrollen abschaffen.', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7854, 9, 16, 'BE', 'Zusätzliche Polizeieinheiten wie die Brennpunkt- und Präsenzeinheit an diesen Orten abbauen, Mittel in soziale Infrastruktur umlenken.', '{901}', null, 1, 3, null, 'Mittel für soziale Infrastruktur können langfristig wirken. Der Abbau gezielter Präsenzeinheiten verzichtet aber auf ein Mittel, das an Brennpunkten laut Studien Kriminalität senkt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7855, 9, 16, 'BE', 'Konzept für ein Frauen*-Nachttaxi als Ergänzung des Nahverkehrs entwickeln.', '{901}', null, 1, 3, null, 'Ein Nachttaxi kann nächtliche Wege sicherer machen und das Sicherheitsgefühl stärken. Bisher ist nur ein Konzept vorgesehen, zur Wirkung gibt es kaum Daten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=68', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7856, 9, 16, 'BE', 'In Großsiedlungen Grünflächen aufwerten und für bessere Beleuchtung sorgen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=32', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7857, 9, 16, 'BE', 'Untersuchungshaft-Überbelegung durch Beschleunigung des Strafprozesses begegnen: richterliche Stellen und Personal zur kriminaltechnischen Auswertung bereitstellen.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=307', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7858, 9, 16, 'BE', 'Digitalisierung der Berliner Justiz vorantreiben und die justizielle IT standardisieren.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=307', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7859, 9, 16, 'BE', 'Typische Armutsdelikte, insbesondere Schwarzfahren, ersatzlos entkriminalisieren; Vollstreckung von Geldstrafen über gemeinnützige Arbeit.', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=311', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7860, 9, 16, 'BE', 'Überwachungsbefugnisse von Polizei und Verfassungsschutz beschränken, keine neuen Befugnisse mittragen; Staatstrojaner und KI-Analyse in Polizeidatenbanken ablehnen.', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=291', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7861, 9, 16, 'BE', 'Ausbau kiezorientierter Gewalt- und Kriminalitätsprävention auf Bezirksebene und Projekte der Jugendsozialarbeit, verlässlich finanziert.', '{903,901}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7862, 9, 16, 'BE', 'Außerschulische Angebote zu Mobbing- und Gewaltprävention für Schulen absichern und verstetigen.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=163', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7863, 9, 16, 'BE', 'Gewalthilfegesetz und Istanbul-Konvention in allen Senatsverwaltungen umsetzen; Landesanteil an der Finanzierung der Anti-Gewalt-Arbeit nicht durch Bundesmittel ersetzen.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7864, 9, 16, 'BE', 'Landeskoordinierungsstelle für die Umsetzung der Istanbul-Konvention einrichten.', '{904}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7865, 9, 16, 'BE', 'Arbeit mit Täter*innen häuslicher Gewalt dauerhaft absichern; Täter*innenkurse verpflichtend anbieten.', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7866, 9, 16, 'BE', 'Fraueninfrastruktur wie Frauenhäuser und Beratungsstellen langfristig sichern, ausbauen und finanziell stärken.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=213', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7867, 9, 16, 'BE', 'Anonyme, vertrauliche Spurensicherung nach sexualisierter Gewalt flächendeckend, dezentral und rund um die Uhr verfügbar machen.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=142', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7868, 9, 16, 'BE', 'Gewaltschutzambulanz ausbauen.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=289', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7869, 9, 16, 'MV', 'Mehr Plätze in Frauenhäusern, barrierefreie Schutzorte sowie Ausbau und dauerhafte Absicherung von Beratungs- und Interventionsstellen und Täterarbeit.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7870, 9, 16, 'MV', 'Landesweites Hochrisikomanagement bei häuslicher Gewalt einführen, mit verbindlichen Verfahren zur Gefährdungseinschätzung besonders gefährdeter Frauen.', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7871, 9, 16, 'MV', 'Polizei durch ausreichende personelle und sachliche Ausstattung unterstützen.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7872, 9, 16, 'MV', 'Kein Einsatz von Staatstrojanern, Vorratsdatenspeicherung oder automatisierter Gesichtserkennung (Verzicht auf diese Ermittlungsbefugnisse).', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=19', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7873, 9, 16, 'MV', 'Keine Nutzung von Palantir und keine allgegenwärtige Videoüberwachung.', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=19', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7874, 9, 16, 'MV', 'E-Akte, Fachverfahren und Schnittstellen zu Polizei und anderen Institutionen interoperabel und zuverlässig gestalten.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=24', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7875, 9, 16, 'MV', 'Arbeitsbedingungen in Gerichten, Staatsanwaltschaften und Justizvollzug verbessern, um die Berufe attraktiv zu machen.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=24', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7876, 9, 16, 'MV', 'Opferambulanzen dauerhaft absichern und personell wie sachlich stärken.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=25', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7877, 9, 16, 'MV', 'Beratungs- und Interventionsstellen für queere Betroffene sexueller und körperlicher Gewalt ausbauen.', '{908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7878, 9, 16, 'ST', '500 zusätzliche Polizeistellen bis 2030 für mehr Präsenz auf der Straße', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7879, 9, 16, 'ST', 'Flächendeckende E-Akte in der Justiz zur Beschleunigung der Verfahren', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=136', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7880, 9, 16, 'ST', 'Freie Stellen in der Justiz schnell besetzen und Fachpersonal durch Assistenz- und IT-Kräfte entlasten', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=136', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7881, 9, 16, 'ST', 'Fahren ohne Fahrschein nicht mehr strafbar machen, um Verfahren zu vermeiden', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=138', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7882, 9, 16, 'ST', 'Ersatzfreiheitsstrafen per Bundesratsinitiative abschaffen', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=140', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7883, 9, 16, 'ST', 'Keine automatisierte Datenanalysesoftware bei der Polizei einführen', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=129', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7884, 9, 16, 'ST', 'Mehr Streetwork, Jugendtreffs und Jugendzentren statt Jugendknast zur Kriminalitätsvorbeugung', '{903,901}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=134', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7885, 9, 16, 'ST', 'Häuser des Jugendrechts für schnelle, behördenübergreifende Reaktionen auf Jugendstraftaten einrichten', '{903}', 7640, 2, 3, null, 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=140', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7886, 9, 16, 'ST', 'Im Jugendstrafrecht erzieherische Wirkung und alternative Maßnahmen statt Freiheitsentzug bevorzugen', '{903}', null, 1, 2, null, 'Erzieherische und ambulante Maßnahmen gehen nicht mit höheren Rückfallraten einher als Freiheitsentzug; Vergleiche sind aber durch Auswahl verzerrt. Das Jugendstrafrecht regelt der Bund, das Land kann ambulante Angebote fördern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=140', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7887, 9, 16, 'ST', 'Frauenberatungsstellen stärken, Eigenanteil im Frauenschutzhaus abschaffen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=21', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7888, 9, 16, 'ST', 'Frauenhausplätze und Zufluchtswohnungen ausbauen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7889, 9, 16, 'ST', 'Bei hoher Risikoeinstufung Näherungsverbot digital überwachen, Sonderzuständigkeiten bei Justiz und Polizei', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7890, 9, 16, 'ST', 'Aufsuchende mobile Beratung für Betroffene häuslicher Gewalt schaffen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=23', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7891, 9, 16, 'ST', 'Anti-Gewalt-Programme für gewaltauffällige Personen als gerichtliche Auflage', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7892, 9, 16, 'ST', 'Schwerpunktstaatsanwaltschaften für geschlechtsspezifische Gewalt einrichten', '{904}', 7649, 1, 3, null, 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=138', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7893, 9, 16, 'ST', 'Femizid als Mordmerkmal im Strafgesetzbuch per Bundesratsinitiative', '{904}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=138', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7894, 9, 16, 'ST', 'Kostenlose Untersuchungen mit gerichtsverwertbarer Dokumentation in Opferschutzambulanzen, Erhalt und Ausbau', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=139', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7895, 9, 16, 'ST', 'Polizeistatistiken und Lagebilder veröffentlichen', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7896, 9, 17, 'BE', 'Intensivere Streifenpräsenz an Brennpunkten wie Bahnhöfen sowie in kriminalitätsbelasteten Parks und Plätzen.', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7897, 9, 17, 'BE', 'Beleuchtung und städtebauliche Kriminalprävention ausbauen, dunkle Ecken in Parks und auf Bahnhofsvorplätzen beseitigen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7898, 9, 17, 'BE', 'Videoüberwachung an besonders kriminalitätsbelasteten Orten, mit parlamentarischer Genehmigung, Echtzeit-Auswertung und längerer Speicherfrist bei BVG- und DB-Kameras.', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7899, 9, 17, 'BE', 'Zusätzliche gemeinsame Kontrollen von Ordnungsamt, Polizei und Zoll, auch im öffentlichen Raum.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7900, 9, 17, 'BE', 'Öffentlichen Drogenkonsum im Umfeld von Schulen und Kitas ahnden, mit Platzverweisen und Sicherheitszonen.', '{901}', null, 1, 3, null, 'Platzverweise und Sicherheitszonen können Drogenkonsum vor Schulen und Kitas zurückdrängen, verlagern ihn aber oft nur. Das Land kann das im Ordnungsrecht regeln; Belege zur Wirkung fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7901, 9, 17, 'BE', 'Einstellungsoffensive bei der Polizei mit Fokus auf qualitativ hochwertige Auswahl.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7902, 9, 17, 'BE', 'Ausstattung der Polizei deutlich verbessern (Schutzkleidung, Fahrzeuge, IT, mobile Geräte) und Investitionsstau abbauen.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7903, 9, 17, 'BE', 'Digitalisierung bei Polizei und Feuerwehr vorantreiben für schnellere Vorgangsbearbeitung und weniger Bürokratie.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7904, 9, 17, 'BE', 'Deutlich mehr Richter- und Staatsanwaltsstellen.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7905, 9, 17, 'BE', 'Beschleunigte Verfahren bei Alltags- und Jugendkriminalität.', '{902,903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7906, 9, 17, 'BE', 'Konsequente Vermögensabschöpfung bei organisierter Kriminalität, Erlöse für Polizei und Feuerwehr.', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7907, 9, 17, 'BE', 'Gemeinsame Ermittlungsgruppen ausbauen.', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7908, 9, 17, 'BE', 'Flächendeckende Präventions- und Anti-Gewaltprogramme an Schulen.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7909, 9, 17, 'BE', 'Präventionsprojekte in stark betroffenen Communities, Ausbau der Jugendarbeit gegen Messerangriffe und schwere Gewalt.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7910, 9, 17, 'BE', 'Elektronische Fußfessel bei Annäherungsverbot mit Warnsystem für Betroffene nach spanischem Modell.', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7911, 9, 17, 'BE', 'Angebot an Frauenhäusern ausbauen, mit mehrsprachigen Hinweisen auf Hilfsangebote.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7912, 9, 17, 'MV', 'Mehr Personal im Streifen- und Ermittlungsdienst, um Präsenz in Problem- und Brennpunktbereichen zu stärken.', '{901,902}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=67', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7913, 9, 17, 'MV', 'Mehr Einsatzkräfte statt Ausweitung der Videoüberwachung im öffentlichen Raum.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=67', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7914, 9, 17, 'MV', 'Zeitgemäße Ausstattung, Technik sowie Aus- und Fortbildung der Polizei.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=67', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7915, 9, 17, 'MV', 'Polizeibesoldung und Zulagen an westliche Länder und den Bund angleichen, bessere Aufstiegschancen.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=68', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7916, 9, 17, 'MV', 'Mehr Richter, Staatsanwälte und Servicekräfte in der Justiz.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=69', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7917, 9, 17, 'MV', 'Schulen mit multiprofessionellen Teams (u. a. Sozialarbeit) ausstatten, um Gewalt vorzubeugen.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7918, 9, 17, 'MV', 'Ausbau von Täterarbeit zur Verhinderung von Wiederholungstaten bei Gewalt gegen Frauen.', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=71', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7919, 9, 17, 'MV', 'Mehr Frauenhausplätze und Schutzwohnungen im ganzen Land, besonders im ländlichen Raum.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7920, 9, 17, 'MV', 'Konsequente Wegweisungen und Annäherungsverbote zum schnellen Schutz Betroffener.', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7921, 9, 17, 'MV', 'Landesaktionsplan gegen Gewalt mit klaren Zuständigkeiten.', '{904}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7922, 9, 17, 'ST', 'Mehr sichtbare Polizeipräsenz in Städten, Vierteln und Dörfern sowie mehr Mittel für attraktive Innenstädte und Quartiere.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7923, 9, 17, 'ST', 'Landespolizei bis 2028 auf rund 7.000 Beamte aufstocken, auch für Präsenz und Ermittlungsarbeit.', '{901,902}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=68', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7924, 9, 17, 'ST', 'Polizei und Ermittlungsbehörden so ausstatten, dass sie gegen organisierte Kriminalität handlungsfähig sind.', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7925, 9, 17, 'ST', 'Keine Palantir-Software und vergleichbare Systeme zur automatisierten Datenverknüpfung bei der Polizei.', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7926, 9, 17, 'ST', 'Richter- und Staatsanwaltsbesoldung verbessern, mehr Planungssicherheit bei Einstellungen, Einstellungsstopp im Justizdienst aufheben.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=71', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7927, 9, 17, 'ST', 'Frauenhäuser, Beratungsstellen und Schutzwohnungen dauerhaft und auskömmlich finanzieren, unabhängig von kommunaler Haushaltslage.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=37', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7928, 9, 17, 'ST', 'Gewaltambulanzen langfristig absichern und landesweit ausbauen, auch telemedizinisch.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7929, 9, 17, 'ST', 'Femizide systematisch erfassen; Landeskriminalamt richtet ein eigenes Monitoring ein.', '{904}', 7647, 1, 3, null, 'Eine einheitliche Erfassung verbessert das Lagebild und kann Prävention gezielter machen. Sie verhindert selbst keine Taten, und zur Wirkung gibt es kaum Daten.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7930, 9, 17, 'ST', 'Verbindlichen Landesaktionsplan zur Umsetzung der Istanbul-Konvention verabschieden.', '{904}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7931, 9, 17, 'ST', 'Mehr Sozialarbeiter in der Jugendarbeit; Gewalt- und Extremismuspräventionsprojekte weiter vom Land fördern.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7998, 9, 12, 'ST', 'Bürokratische Belastungen der Polizei werden reduziert, damit sich Beschäftigte auf Kernaufgaben konzentrieren können.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'offen', '2026-10-05', false, true, 'blind'),
  (7999, 9, 14, 'MV', 'Polizei von Bürokratie entlasten: Dokumentationspflichten und interne Verwaltungsaufgaben deutlich reduzieren und auf Verwaltungsangestellte übertragen.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8000, 9, 15, 'MV', 'Die im Landespolizeigesetz (SOG) beschlossenen Dokumentationspflichten für die Polizei sollen sofort zurückgenommen werden.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8002, 9, 11, 'BE', 'Berichts- und Dokumentationspflichten der Polizei stark zurückfahren und überarbeiten', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8003, 9, 11, 'MV', 'Durch Technik, Automatisierung und KI den Zeitanteil bürokratischer Routineprozesse im Polizeidienst deutlich verringern, damit mehr Zeit für Prävention und Strafverfolgung bleibt.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=28', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8512, 9, 18, null, 'Länder und Kommunen beim Gewinnen von Personal für Polizei und Ordnungsbehörden unterstützen, Ausbildungen attraktiver machen.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=33', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8513, 9, 18, null, 'Anzeigenaufnahme bis Staatsanwaltschaft vollständig digitalisieren.', '{902}', 7483, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=35', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8514, 9, 18, null, 'Opportunitätsprinzip ausweiten, damit Polizeiressourcen gezielter eingesetzt werden.', '{902}', null, 1, 2, null, 'Ein weiteres Opportunitätsprinzip kann Ressourcen auf schwere Taten lenken. Zugleich bleiben mehr kleine Taten ohne Folgen, und zur Wirkung auf die Aufklärung gibt es kaum Daten; die Abkehr vom Legalitätsprinzip ist rechtlich umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=35', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8515, 9, 18, null, 'Bodycams, Berichterstattungssysteme und Analysewerkzeuge stärker in den Polizeidienst integrieren.', '{902}', null, 1, 2, null, 'Bessere Technik kann Dokumentation und Auswertung erleichtern. Eine Übersichtsstudie fand bei Bodycams aber keine Wirkung auf Festnahmen, nur weniger Beschwerden; der Bund steuert nur die Bundespolizei.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=34', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8516, 9, 18, null, 'Schwarzfahren zur Ordnungswidrigkeit herabstufen, keine Ersatzfreiheitsstrafen mehr.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', null, 'belegt', '2026-10-07', false, true, 'blind'),
  (8517, 9, 18, null, 'Besitz und Gebrauch aller psychoaktiven Substanzen sanktionsfrei stellen.', '{902}', null, 1, 2, null, 'In Portugal entlastete die Entkriminalisierung des Konsums Justiz und Gefängnisse ohne starken Anstieg des Konsums. Eine völlig sanktionsfreie Regel geht weiter und steht in Spannung zu UN-Drogenkonventionen; schwere Taten werden nur indirekt schneller verfolgt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=154', 'https://kar.kent.ac.uk/29910/', 'belegt', '2026-10-07', false, true, 'blind'),
  (8518, 9, 18, null, 'Spezialeinheiten gegen organisierte Kriminalität bei BKA, Zoll und in den Ländern personell verstärken.', '{902}', null, 1, 2, null, 'Mehr Personal für Spezialeinheiten stärkt Ermittlungen gegen organisierte Kriminalität. Auf die Aufklärung alltäglicher Straftaten wirkt es kaum; der Bund steuert nur BKA und Zoll, Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=35', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8519, 9, 18, null, 'Cybercrime-Einheiten von Polizei und Justiz stärken.', '{906}', null, 2, 2, null, 'Mehr spezialisierte Ermittler können mehr Online-Taten aufklären. Viele Taten kommen aber aus dem Ausland, wo die Aufklärung gering bleibt; der Umfang ist offen, und die meisten Einheiten unterstehen den Ländern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=34', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8520, 9, 18, null, 'Europol zu einer europäischen Polizei mit Exekutivrechten ausbauen, gegen grenzüberschreitende Kriminalität.', '{906,907}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=31', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8521, 9, 18, null, 'Strafrahmen für Hasskriminalität und Unterstützung extremistischer Ideologien, besonders online, verschärfen.', '{907}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=18', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-07', false, true, 'blind'),
  (8522, 9, 18, null, 'Bildungsprogramme und zivilgesellschaftliche Initiativen gegen extremistische Ideologien fördern.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8523, 9, 18, null, 'Deradikalisierungsprogramme und Ausstiegshilfen fördern.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8524, 9, 18, null, 'Zusammenarbeit mit internationalen Partnern intensivieren, um extremistische Netzwerke und Online-Plattformen zu zerschlagen.', '{907}', null, 1, 2, null, 'Extremistische Netzwerke und Plattformen agieren oft grenzüberschreitend, engere Zusammenarbeit setzt dort an. Ohne konkretes Instrument bleibt die Wirkung unbestimmt, und sie hängt von der Mitwirkung anderer Staaten ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8525, 9, 18, null, 'Schutzkonzepte für jüdische Gemeinden entwickeln, Antisemitismusbeauftragte und Meldestellen ausbauen.', '{907}', null, 2, 2, null, 'Bauliche Sicherung und Schutzkonzepte können Anschläge abwehren, wie die gesicherte Tür in Halle 2019 zeigte; Meldestellen machen Taten sichtbar. Objektschutz liegt bei den Ländern, und Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=145', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8526, 9, 18, null, 'Keine Abschiebung von Personen mit Arbeits-, Ausbildungs- oder Studienplatz, die nicht straffällig wurden.', '{905}', null, 1, 3, null, 'Eine Studie aus Italien zeigt, dass ein gesicherter Aufenthalt mit legaler Arbeit die Straffälligkeit von Zugewanderten etwa halbiert. Die Maßnahme betrifft aber nur Menschen, die schon arbeiten und nicht straffällig sind.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=139', 'https://swlb1.aeaweb.org/research/legalizing-immigrants-impact-crime-rate', 'belegt', '2026-10-07', false, true, 'blind'),
  (8527, 9, 18, null, 'Straffällige Jugendliche durch Präventionsmaßnahmen frühzeitig unterstützen.', '{903}', null, 2, 2, null, 'Eine Meta-Analyse zeigt weniger Rückfälle bei therapeutisch ausgerichteten, gut umgesetzten Programmen für straffällige Jugendliche. Welche Maßnahmen gemeint sind, bleibt offen; Jugendhilfe liegt bei Ländern und Kommunen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=38', 'https://ojp.gov/ncjrs/virtual-library/abstracts/primary-factors-characterize-effective-interventions-juvenile', 'belegt', '2026-10-07', false, true, 'blind'),
  (8528, 9, 18, null, 'Plätze in Frauenhäusern ausbauen, kostenloser Zugang für Schutzbedürftige.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-07', false, true, 'blind'),
  (8529, 9, 18, null, 'Tatpersonen geschlechtsspezifischer Gewalt müssen Kurse in gewaltfreier Kommunikation absolvieren.', '{904}', 7496, 2, 2, null, 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8530, 9, 18, null, 'Strafbarkeit auf neue Formen von Belästigung und Gewalt gegen Frauen erweitern, konsequente Verfolgung.', '{904}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-07', false, true, 'blind'),
  (8531, 9, 18, null, 'Vergewaltigung als medizinischen Notfall behandeln, bundesweit anonyme 24/7-Gewalt- und Forensik-Notdienste einführen.', '{908}', null, 2, 2, null, 'Spezialisierte forensische Notdienste (SANE) gingen in US-Studien mit häufigeren Verurteilungen einher, einzelne Standorte zeigten aber keinen Effekt. Ein bundesweiter 24/7-Dienst braucht Länder, Kliniken und Personal.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://crimesolutions.ojp.gov/ratedprograms/sexual-assault-nurse-examiner-sane-program-multisite', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8643, 9, 18, 'BE', 'Konzept für sichere Grün-, Bewegungs- und öffentliche Räume, etwa mit besserer Beleuchtung und Begrünung', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-08', false, true, 'blind'),
  (8644, 9, 18, 'BE', 'Digitale Meldesysteme, über die Bürger unsichere Orte anonym markieren können', '{901}', null, 1, 3, null, 'Anonyme Meldungen zeigen, wo sich Menschen unsicher fühlen, und können Beleuchtung oder Streifen gezielter lenken, wie Projekte in Australien versuchen. Ob das die Sicherheit verbessert, ist nicht untersucht und hängt von den Folgemaßnahmen ab.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8645, 9, 18, 'BE', 'Aufsuchende Sozialarbeit und Präsenz statt Repression im Umgang mit Drogenkonsum', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=84', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8646, 9, 18, 'BE', 'Bessere Personalausstattung von Polizei und Justiz für höhere Streifendichte und konsequente Strafverfolgung', '{901,902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=76', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8647, 9, 18, 'BE', 'Aufgabenverteilung zwischen Polizei und Ordnungsdiensten, damit sich die Polizei auf Kernaufgaben konzentriert', '{902}', null, 1, 2, null, 'Eine klarere Aufgabenteilung kann Polizeikräfte für Ermittlungen und Einsätze frei machen. Wie viel Zeit das bringt und ob mehr Taten aufgeklärt werden, ist kaum untersucht; die kommunalen Ordnungsdienste brauchen dafür selbst Personal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=76', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8648, 9, 18, 'BE', 'Polizei mit digitalen Tools modernisieren (E-Akte, KI bei Einsatzberichten) mit Datenschutzregeln', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8649, 9, 18, 'BE', 'Bodycams verpflichtend einschalten, alle Kräfte ausstatten, Löschen durch Beamte verhindern', '{902}', 8640, 1, 3, null, 'Laut Campbell-Übersichtsstudie senken Bodycams Beschwerden etwas, Gewaltanwendung und Festnahmen aber nicht verlässlich; Folgen für Aufklärung und Verurteilungen sind kaum untersucht. Das Land kann Einsatz und Pflichten im Polizeigesetz regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8650, 9, 18, 'BE', 'Bürger- und Polizeibeauftragten mit Aktenzugang und Ermittlungskompetenzen ausstatten', '{902}', 8641, 1, 3, null, 'Polizeigewalt wird laut einer Opferbefragung (KviAPol) nur selten angezeigt und verfolgt; eine unabhängige Stelle setzt dort an. Ob solche Stellen mehr Taten aufklären, ist kaum untersucht, und sie betreffen nur einen kleinen Teil der Straftaten.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', 'https://www.lto.de/recht/nachrichten/n/studie-polizeigewalt-singelnstein-zwischenbericht', 'offen', '2026-10-08', false, true, 'blind'),
  (8651, 9, 18, 'BE', 'Strafverfahren wegen Besitzes geringer Mengen zum Eigenbedarf einstellen, Grenzwerte anheben', '{902}', 8642, 1, 3, null, 'Allein Fahren ohne Fahrschein führte 2021 zu über 38.000 Verurteilungen und fast einem Viertel der Ersatzfreiheitsstrafen; Einstellungsrichtlinien des Landes entlasten die Justiz rasch. Schwerere Taten werden dadurch nur indirekt schneller verfolgt.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=84', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-08', false, true, 'blind'),
  (8652, 9, 18, 'BE', 'Auf Bundesebene Beweislastumkehr für Vermögen organisierter Kriminalität einführen', '{902}', 7656, 1, 1, null, 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8653, 9, 18, 'BE', 'Gefährdete oder straffällige Jugendliche früh unterstützen: Schulen, Streetwork, Jugendhilfe stärken', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=74', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8654, 9, 18, 'BE', 'Fußfessel für Täter häuslicher Gewalt, damit sie sich Opfern nicht unbemerkt nähern können', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=75', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8655, 9, 18, 'BE', 'Frauenhausplätze ausbauen, um Vorgaben der Istanbul-Konvention zu erfüllen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=75', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-08', false, true, 'blind'),
  (8656, 9, 18, 'BE', 'Rahmenkonzept zum Gefährdungsmanagement und multiinstitutionelle Fallkonferenzen gegen Stalking und Gewalt umsetzen', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=75', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8657, 9, 18, 'MV', 'Landeskoordinierungsstelle gegen häusliche und sexualisierte Gewalt wieder einrichten und elektronische Fußfessel gegen Wiederholungstaten einführen.', '{904,908}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=14', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8658, 9, 18, 'MV', 'Schutzhäuser deutlich ausbauen und dauerhaft finanzieren, inklusive anonymer Spurensicherung; mindestens eine Beratungsstelle je Landkreis.', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-08', false, true, 'blind'),
  (8659, 9, 18, 'MV', 'Kommunale Lichtkonzepte und Bildungskampagnen zur Prävention von Femiziden unterstützen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-08', false, true, 'blind'),
  (8660, 9, 18, 'MV', 'Beamte zum Einsatz von Bodycams zur Einsatzdokumentation verpflichten.', '{902}', 8640, 1, 3, null, 'Laut Campbell-Übersichtsstudie senken Bodycams Beschwerden etwas, Gewaltanwendung und Festnahmen aber nicht verlässlich; Folgen für Aufklärung und Verurteilungen sind kaum untersucht. Das Land kann Einsatz und Pflichten im Polizeigesetz regeln.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8661, 9, 18, 'MV', 'Unabhängige Ermittlungsstelle für mutmaßliche Polizeigewalt beim Justizministerium einrichten.', '{902}', 8641, 1, 3, null, 'Polizeigewalt wird laut einer Opferbefragung (KviAPol) nur selten angezeigt und verfolgt; eine unabhängige Stelle setzt dort an. Ob solche Stellen mehr Taten aufklären, ist kaum untersucht, und sie betreffen nur einen kleinen Teil der Straftaten.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://www.lto.de/recht/nachrichten/n/studie-polizeigewalt-singelnstein-zwischenbericht', 'offen', '2026-10-08', false, true, 'blind'),
  (8662, 9, 18, 'MV', 'Auf Palantir und vergleichbare intransparente Analyseplattformen bei der Polizei verzichten.', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=45', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8663, 9, 18, 'MV', 'Schul- und Jugendsozialarbeit dauerhaft mit Landesmitteln fördern, auch zur Präventionsarbeit.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=14', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8664, 9, 18, 'ST', 'Polizei im ländlichen Raum sichtbarer machen: mobile Wachen und regelmäßige Präsenzpunkte in Gemeinden.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=167', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8665, 9, 18, 'ST', 'Kommunale Präventionsmaßnahmen wie Licht- und Raumkonzepte verstärkt unterstützen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-08', false, true, 'blind'),
  (8666, 9, 18, 'ST', 'Kampagne „Ist Luisa hier?“ landesweit in Clubs, Bars und bei Veranstaltungen umsetzen.', '{908}', null, 1, 3, null, 'Ein Codewort in Clubs und Bars verschafft Betroffenen von Belästigung schnelle Hilfe vor Ort und ist günstig umzusetzen. Ob es Übergriffe verhindert oder Anzeigen erhöht, ist nicht untersucht; es erreicht nur das Nachtleben.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=173', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8667, 9, 18, 'ST', 'Einstellungsverfahren der Landespolizei durch parallele Prüfabläufe beschleunigen, um Personal zu gewinnen.', '{902}', null, 1, 3, null, 'Schnellere Einstellungsverfahren verringern den Verlust von Bewerbern an andere Arbeitgeber. Sie schaffen aber keine zusätzlichen Stellen oder Bewerber, und zur Wirkung auf die Personalstärke gibt es kaum Daten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=166', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8668, 9, 18, 'ST', 'Ausreichend Personal in Gerichten und Staatsanwaltschaften gewährleisten.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=175', null, 'belegt', '2026-10-08', false, true, 'blind'),
  (8669, 9, 18, 'ST', 'Verbindliche Zielzeiten für Strafverfahren einführen.', '{902}', null, 1, 2, null, 'Zielzeiten machen lange Verfahren sichtbar und können die Steuerung verbessern. Ohne mehr Personal bleibt der Effekt begrenzt, für Gerichte setzt die richterliche Unabhängigkeit verbindlichen Vorgaben Grenzen, und Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=175', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8670, 9, 18, 'ST', 'KI-Assistenzsysteme an Gerichten erproben und einführen, um Verfahren zu beschleunigen.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=176', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8671, 9, 18, 'ST', 'Geringfügige Verfahren (Schwarzfahren) durch Staatsanwaltschaften öfter einstellen.', '{902}', 8642, 1, 3, null, 'Allein Fahren ohne Fahrschein führte 2021 zu über 38.000 Verurteilungen und fast einem Viertel der Ersatzfreiheitsstrafen; Einstellungsrichtlinien des Landes entlasten die Justiz rasch. Schwerere Taten werden dadurch nur indirekt schneller verfolgt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=177', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-08', false, true, 'blind'),
  (8672, 9, 18, 'ST', 'Bodycams im Polizeidienst einsetzen.', '{902}', 8640, 1, 3, null, 'Laut Campbell-Übersichtsstudie senken Bodycams Beschwerden etwas, Gewaltanwendung und Festnahmen aber nicht verlässlich; Folgen für Aufklärung und Verurteilungen sind kaum untersucht. Das Land kann Einsatz und Pflichten im Polizeigesetz regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8673, 9, 18, 'ST', 'Unabhängige Ermittlungsstelle für mutmaßliche Polizeigewalt beim Justizministerium einrichten.', '{902}', 8641, 1, 3, null, 'Polizeigewalt wird laut einer Opferbefragung (KviAPol) nur selten angezeigt und verfolgt; eine unabhängige Stelle setzt dort an. Ob solche Stellen mehr Taten aufklären, ist kaum untersucht, und sie betreffen nur einen kleinen Teil der Straftaten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://www.lto.de/recht/nachrichten/n/studie-polizeigewalt-singelnstein-zwischenbericht', 'offen', '2026-10-08', false, true, 'blind'),
  (8674, 9, 18, 'ST', 'Sonderdezernat für Finanzkriminalität und organisierte Kriminalität bei allen Staatsanwaltschaften.', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=168', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8675, 9, 18, 'ST', 'Ordnungsämter, Zoll, Polizei und weitere Behörden besser vernetzen.', '{902}', null, 1, 3, null, 'Gemeinsame Kontrollen mehrerer Behörden können Verstöße und Strukturen sichtbar machen, die einzelne Stellen übersehen. Ohne konkreten Auftrag bleibt die Wirkung auf die Aufklärung von Straftaten unbestimmt, Studien dazu fehlen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=168', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8676, 9, 18, 'ST', 'Frauen- und Schutzhäuser ausbauen und dauerhaft finanzieren.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-08', false, true, 'blind'),
  (8677, 9, 18, 'ST', 'Elektronische Fußfesseln bei Hochrisikotätern nutzen, um Femizide zu verhindern.', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8678, 9, 18, 'ST', 'Täterarbeit intensivieren, etwa mit Anti-Aggressionstrainings.', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8679, 9, 18, 'ST', 'Anonyme Spurensicherung als niedrigschwelligen Zugang zur Beweissicherung ausweiten.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8680, 9, 18, 'ST', 'Prioritätsverfahren und spezialisierte Richter für Gewaltfälle gegen Frauen.', '{904}', 7649, 1, 3, null, 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=125', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8681, 9, 18, 'ST', 'Zentrale Landeskoordinierungsstelle gegen häusliche und sexualisierte Gewalt einrichten.', '{904,908}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', null, 'offen', '2026-10-08', false, true, 'blind');

